INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4281', 'spa', 'Ir adelante, avanzar o preceder a otros; progresar hacia adelante en espacio o tiempo.', 'Describe la acción de ir por delante de un grupo o avanzar más allá de la posición actual. En los Evangelios, Jesús «se adelantó un poco» para orar a solas en Getsemaní (Mt 26:39; Mr 14:35), las multitudes corrieron por delante para encontrarse con él (Mr 6:33), y Judas iba al frente del grupo que venía a arrestarlo (Lc 22:47). Lucas 1:17 lo usa proféticamente sobre Juan el Bautista, quien iría «delante» del Señor con el espíritu de Elías. El significado central es la prioridad espacial — ir por delante de alguien — con una dimensión tanto física como preparatoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4286', 'spa', 'Propósito, resolución deliberada o plan; también la presentación de los panes de la proposición ante Dios. Construido a partir del verbo προτίθημι (''p', 'Propósito, resolución deliberada o plan; también la presentación de los panes de la proposición ante Dios. Construido a partir del verbo προτίθημι (''poner delante''), este sustantivo posee dos sentidos bastante distintos en el Nuevo Testamento. Con mayor frecuencia designa el propósito eterno de Dios o la resolución firme de una persona: Pablo habla de la πρόθεσις de Dios que dispone todas las cosas conforme al consejo de su voluntad (Ro 8:28; Ef 1:11; 2 Ti 1:9). En su sentido más antiguo y concreto, la palabra se refiere al acto ritual de colocar panes ante Dios — los ''panes de la proposición'' o pan de la Presencia que David comió en su hora de necesidad (Mt 12:4; Mr 2:26; Lc 6:4) y la mesa de los panes en el tabernáculo (He 9:2). Ambos sentidos comparten la imagen raíz de colocar algo al frente, ya sea un plan ante la mente o panes ante el Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4288', 'spa', 'Prontitud, disposición, buena voluntad; celo entusiasta y disposición para actuar, especialmente en la generosidad.', 'Sustantivo que denota disposición entusiasta y prontitud de ánimo, derivado de πρόθυμος (pronto, dispuesto). Cuatro de sus cinco apariciones en el NT se encuentran en 2 Corintios 8-9, donde Pablo elogia la «prontitud» de los macedonios al contribuir a la colecta para los pobres de Jerusalén. En Hechos 17:11, los bereanos reciben la palabra con toda «buena disposición», examinando las Escrituras cada día. El término subraya el aspecto volitivo: no se trata de una mera obligación, sino de un impulso interior genuino que se traduce en acción concreta, especialmente en el ámbito de la generosidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4289', 'spa', 'Dispuesto, presto, deseoso; preparado y con ánimo para actuar', 'Este adjetivo describe disposición, voluntad y anhelo de actuar. En el uso clásico enfatizaba tanto la actitud interior como el celo activo. El Nuevo Testamento lo emplea para contrastar el espíritu dispuesto con la debilidad de la carne, y para expresar el fervoroso deseo de Pablo de predicar el evangelio. El término abarca tanto la disposición interna del corazón como la preparación exterior para la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4291', 'spa', 'Dirigir, administrar o presidir; gobernar asuntos con cuidado y diligencia.', 'Verbo compuesto que significa literalmente ''estar al frente'', προΐστημι combina la idea de liderazgo con la de cuidado solícito. Pablo lo emplea para describir a los ancianos que ''presiden'' la comunidad (1 Ts 5:12; 1 Ti 5:17) y para la administración del hogar como requisito de los obispos (1 Ti 3:4-5, 12). En Romanos 12:8 aparece entre los dones espirituales: quien dirige debe hacerlo con diligencia. Las Epístolas Pastorales desarrollan especialmente el paralelo entre gobernar bien un hogar y gobernar la iglesia de Dios, convirtiendo este verbo en piedra angular del vocabulario neotestamentario sobre el liderazgo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4295', 'spa', 'Estar puesto delante, yacer ante alguien; estar presente, disponible o expuesto públicamente como meta o ejemplo.', 'Verbo que significa yacer o estar puesto delante de alguien: estar presente, disponible o expuesto públicamente. Funciona como pasivo de προτίθημι (poner delante). En 2 Cor 8:12, la disposición que «está presente» (πρόκειται) determina la ofrenda aceptable. Hebreos lo emplea con gran fuerza: los creyentes se aferran a la esperanza «puesta delante» de ellos (6:18), y Jesús soportó la cruz por el gozo «puesto delante» de él (12:2). Hebreos 12:1 habla de la carrera «que nos está propuesta». Judas 7 describe a Sodoma y Gomorra como «puestas por ejemplo» de juicio. La voz pasiva subraya que algo ha sido colocado ante la persona por un agente externo, frecuentemente Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4297', 'spa', 'Progreso, avance; movimiento hacia adelante en el desarrollo moral, espiritual o intelectual', 'Este sustantivo denota progreso o avance, particularmente en el desarrollo moral, espiritual o intelectual. Las fuentes clásicas lo usaban para el avance en un viaje, la competencia en el aprendizaje o la promoción militar. Pablo lo emplea dos veces en Filipenses y una vez en las Epístolas Pastorales para describir el adelanto del evangelio o el crecimiento en la piedad. El término enfatiza un progreso visible y constatable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4298', 'spa', 'προκόπτω -- avanzar, progresar, ir hacia adelante (siempre metafórico en el NT).', 'Con el significado original de «cortar hacia adelante» (como pioneros abriendo camino), προκόπτω se emplea exclusivamente en sentido metafórico en el Nuevo Testamento. Describe progreso o avance en diversos ámbitos: el niño Jesús creciendo en sabiduría y estatura (Lc 2:52), el antiguo celo de Pablo avanzando en el judaísmo (Gal 1:14), la noche que «avanza» hacia el amanecer (Rom 13:12) y los falsos maestros que progresan cada vez más en la impiedad (2 Ti 2:16; 3:9, 13). Así, la palabra posee una valencia neutra: el progreso puede ser positivo o negativo según lo que avanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4301', 'spa', 'Tomar de antemano, anticiparse, recibir por adelantado; ser sorprendido o hallado en un acto', 'Este verbo significa tomar o recibir de antemano, anticiparse, o ser sorprendido o alcanzado en algo. El uso clásico incluía recibir un pago por adelantado, apoderarse de algo antes que otro o adelantarse a alguien. El Nuevo Testamento lo emplea en contextos variados: para una acción anticipada, para ser sorprendido en pecado, y posiblemente para tomar algo antes del momento apropiado. Abarca tanto la iniciativa previsora como el ser hallado en falta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4302', 'spa', 'Decir o anunciar de antemano, ya sea como declaración previa, predicción profética o advertencia solemne con fuerza admonitoria.', 'Decir o anunciar de antemano, ya sea como declaración previa, predicción profética o advertencia solemne con fuerza admonitoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4306', 'spa', 'Pensar con anticipacion, proveer, cuidar de antemano; planificar o velar por algo con prevision', 'Este verbo significa pensar con anticipacion, proveer o preocuparse de antemano por algo. En el griego clasico se empleaba para la prevision, la planificacion y la providencia, incluyendo el conocimiento previo divino. En el Nuevo Testamento se aplica a la responsabilidad etica: proveer para la propia familia y mantener una conducta honorable ante todos. El enfasis recae en la prevision y la planificacion responsable como expresion de fe practica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4308', 'spa', 'Ver de antemano, prever; percibir anticipadamente o mantener algo constantemente a la vista.', 'Combina el prefijo προ- (antes, delante) con ὁράω (ver), produciendo un verbo que puede significar tanto prever acontecimientos futuros como mantener algo constantemente ante los ojos. Pedro en Pentecostés cita a David: «Veía al Señor siempre delante de mí» (Hch 2:25, del Sal 16:8), donde el sentido es mantener la mirada fija en Dios. En Hechos 2:31, David previó la resurrección. En Gálatas 3:8, la Escritura misma «previó» que Dios justificaría a los gentiles. El vocablo tiende un puente entre la previsión profética y la visión atenta y sostenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4309', 'spa', 'προορίζω -- predestinar, preordenar, determinar de antemano por decreto divino.', 'El verbo compuesto προορίζω (προ- «antes» + ὁρίζω «fijar un límite, determinar») es un término teológico de gran peso que significa decidir o designar algo con anticipación. Las seis ocurrencias en el NT tienen a Dios como agente implícito o explícito, lo que convierte a esta palabra en una declaración sobre la soberanía divina respecto al curso de la historia y la salvación. Pablo la emplea para describir el plan eterno de Dios de conformar a los creyentes a la imagen de Cristo (Rom 8:29-30), adoptarlos como hijos (Ef 1:5, 11) y preparar una sabiduría oculta para su gloria (1 Co 2:7). En Hch 4:28 describe la mano soberana de Dios detrás de la crucifixión misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4311', 'spa', 'Encaminar, acompañar en el viaje; despedir a alguien proveyéndole de lo necesario para el camino.', 'Un término entrañable de la hospitalidad cristiana primitiva que describe la práctica de escoltar a un viajero en la primera etapa de su camino, a menudo proveyéndole de provisiones para la ruta. Cuando la iglesia de Antioquía ''encaminó'' a Pablo y Bernabé (Hch 15:3), o cuando los ancianos de Éfeso acompañaron a Pablo hasta el barco (Hch 20:38), la palabra transmite matices de cuidado comunitario y despedida en oración. El propio Pablo espera ser ''encaminado'' por la iglesia de Roma hacia España (Ro 15:24). El vocablo se distingue del mero despachar por su dimensión personal y relacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4314', 'spa', 'A, hacia; para; con; ante, junto a; entre; contra; conforme a; por causa de', 'La preposicion griega πρός es una de las palabras relacionales mas versatiles del griego, capaz de regir acusativo, dativo y (raramente) genitivo con matices distintos. En el Nuevo Testamento predomina con acusativo, expresando movimiento hacia una persona o lugar. El prologo del Evangelio de Juan declara que el Verbo estaba πρὸς τὸν θεόν — hacia Dios, con Dios, cara a cara con Dios — condensando fuerza direccional, asociativa y relacional en dos palabras. Mas alla de su nucleo espacial, πρός se extiende al proposito (''para''), la compania (''con''), la proximidad (''ante, junto a''), la oposicion (''contra'') y la conformidad (''conforme a''). Su amplitud semantica la hace indispensable para expresar toda la gama de relaciones interpersonales y teologicas en las epistolas y los Evangelios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4317', 'spa', 'Acercar, conducir hacia, presentar ante alguien; conceder acceso o aproximación.', 'Significa llevar a alguien o algo hacia adelante, hasta la presencia de otro, combinando πρός (hacia) con ἄγω (conducir). Jesús ordena que le traigan al muchacho (Lc 9:41). En Hechos, Pablo y Silas son arrastrados ante los magistrados (Hch 16:20), y los marineros perciben que la tierra se acerca (Hch 27:27). El uso más notable aparece en 1 Pedro 3:18, donde Cristo padeció para «llevarnos a Dios», el acto supremo de προσαγωγή. La palabra transita desde el simple acto físico de conducir hasta el profundo concepto teológico del acceso a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4318', 'spa', 'Acceso, aproximacion; el privilegio de acercarse o ser introducido en la presencia de alguien', 'Este sustantivo designa el acceso o la aproximacion, particularmente el privilegio de entrar en la presencia de alguien. En el uso clasico incluia las aproximaciones solemnes en festivales, la presentacion ante un rey y el acercamiento a lugares sagrados. Pablo lo emplea exclusivamente para describir el acceso que los creyentes tienen a Dios por medio de Cristo, un privilegio espiritual revolucionario que el evangelio hace posible mediante la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4319', 'spa', 'Mendigo; persona que pide limosna o vive de la mendicidad', 'Este sustantivo identifica a un mendigo, es decir, alguien que pide limosna y vive solicitando ayuda de otros. En el uso clasico abarcaba tanto el acto de mendigar como la persona que mendiga. En el Nuevo Testamento aparece exclusivamente en los Evangelios para describir a personas que buscan ayuda, siendo el ejemplo mas notable el mendigo ciego Bartimeo. El termino subraya tanto la ocupacion de la persona como su condicion social de dependencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4327', 'spa', 'Esperar o aguardar algo anticipado, o recibir y acoger a alguien o algo con favor y aceptación.', 'Esperar o aguardar algo anticipado, o recibir y acoger a alguien o algo con favor y aceptación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4328', 'spa', 'Esperar, aguardar (con anticipación paciente); prever, anticipar (suposición mental). El verbo προσδοκάω describe la postura humana de expectación en ', 'Esperar, aguardar (con anticipación paciente); prever, anticipar (suposición mental). El verbo προσδοκάω describe la postura humana de expectación en el Nuevo Testamento, ya sea esperanzada, ansiosa o calculadora. En su sentido primario transmite una espera paciente y corporal: la multitud de Zacarías ''lo esperaba'' fuera del templo (Lc 1:21), el pueblo ''esperaba'' si Juan pudiera ser el Cristo (Lc 3:15), y Juan el Bautista envía discípulos a preguntar ''¿eres tú el que ha de venir, o debemos esperar a otro?'' (Mt 11:3; Lc 7:19-20). Un segundo grupo desplaza el énfasis de la espera corporal a la anticipación mental o suposición: el señor ''vendrá el día que el siervo no espera'' (Mt 24:50; Lc 12:46), y los malteses ''esperaban'' que Pablo se hinchara o cayera muerto (Hch 28:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4331', 'spa', 'acercarse, aproximarse, allegarse; moverse hacia alguien o algo en proximidad', 'Este verbo compuesto significa acercar o aproximarse, funcionando tanto transitivamente (acercar algo) como intransitivamente (allegarse o aproximarse). En el griego bíblico y posbíblico describía comúnmente el acercamiento a una persona, un lugar o un momento en el tiempo. La voz media enfatizaba la implicación personal en el acto de acercarse. Aunque era poco frecuente en textos clásicos, cobró vigencia en el griego helenístico y aparece en el Nuevo Testamento al hablar de aproximarse a Dios, a espacios sagrados o a acontecimientos escatológicos. El sentido espacial a menudo portaba matices espirituales o relacionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4334', 'spa', 'Acercarse, venir hacia, aproximarse; movimiento físico hacia una persona, acercamiento cultual a Dios, o visita con propósito.', 'Uno de los verbos de movimiento más frecuentes en los Evangelios, προσέρχομαι aparece abrumadoramente en Mateo como fórmula narrativa: alguien ''se acercó'' a Jesús y le habló. Sin embargo, el vocablo adquiere una resonancia más profunda en Hebreos, donde se convierte en el término técnico para acercarse a Dios en adoración, evocando el lenguaje sacerdotal veterotestamentario de aproximarse al altar. Los sentidos físico y espiritual se enlazan por la direccionalidad inherente de la palabra: movimiento hacia una persona o presencia significativa. El español acercándose y el francés s''approcher cubren el espectro con elegancia, mientras que el alemán hinzutreten capta la cualidad formal y deliberada especialmente prominente en Hebreos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4335', 'spa', 'Oración — el acto de orar o una oración específica ofrecida, especialmente dirigida a Dios en petición y adoración.', 'Oración — el acto de orar o una oración específica ofrecida, especialmente dirigida a Dios en petición y adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4336', 'spa', 'Orar: dirigirse a Dios en petición, súplica, intercesión o adoración.', 'El griego προσεύχομαι es el verbo principal del Nuevo Testamento para la oración dirigida a Dios. Abarca todo el espectro de la comunicación orante: la petición personal (Mat 6:5-6), la intercesión por otros (Mat 5:44), la oración solitaria prolongada (Mat 14:23) y la adoración comunitaria. La vida de oración de Jesús se describe frecuentemente con este verbo, estableciendo un modelo para los discípulos. A diferencia de αἰτέω (que enfatiza el pedir) o δέομαι (que subraya la necesidad urgente), προσεύχομαι enmarca la oración como un acto de volverse hacia Dios en reverente invocación. El español orando, el francés prier y el alemán beten conservan esta orientación devocional. El vocablo aparece en el léxico de todos los autores principales del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4337', 'spa', 'Prestar atención, poner cuidado; guardarse, estar en guardia contra; dedicarse a algo', 'Prestar atención, poner cuidado; guardarse, estar en guardia contra; dedicarse a algo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4339', 'spa', 'Prosélito; gentil convertido al judaísmo que ha adoptado la fe y las prácticas judías.', 'Derivado de una raíz que significa «el que se ha acercado» o «llegado», este término designa al gentil que se ha convertido formalmente al judaísmo, abrazando su pacto, su ley y su culto. En el Nuevo Testamento aparece en contextos que van desde la aguda crítica de Jesús a los esfuerzos proselitistas de los fariseos (Mt 23:15) hasta la vibrante escena multicultural de Pentecostés, donde prosélitos de muchas naciones oyeron el evangelio (Hch 2:11). Las traducciones en diversas lenguas conservan uniformemente la forma transliterada «prosélito», lo que refleja su carácter técnico como categoría religiosa y social reconocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4340', 'spa', 'Temporal, pasajero; que dura solo un tiempo, transitorio, no perdurable.', 'Este adjetivo traza una línea nítida entre lo pasajero y lo eterno. Formado a partir de πρός (hacia) y καιρός (tiempo oportuno, estación), describe aquello que pertenece solo a un momento determinado y no perdurará. Pablo lo emplea en un contraste poderoso: «las cosas que se ven son temporales, pero las que no se ven son eternas» (2 Co 4:18). En la parábola del sembrador, caracteriza a quienes su fe se marchita bajo la presión porque carece de raíz profunda (Mt 13:21; Mr 4:17). El vocablo subraya la fugacidad de lo mundano frente a la permanencia de lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4341', 'spa', 'Convocar o llamar hacia sí, usado de manera característica cuando Jesús reúne a discípulos o multitudes', 'Convocar o llamar hacia sí, usado de manera característica cuando Jesús reúne a discípulos o multitudes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4342', 'spa', 'Persistir firmemente en una actividad (especialmente la oración o la enseñanza); también atender constantemente a una persona. El verbo προσκαρτερέω c', 'Persistir firmemente en una actividad (especialmente la oración o la enseñanza); también atender constantemente a una persona. El verbo προσκαρτερέω combina πρός (''hacia'') con καρτερέω (''ser constante, perseverar''), produciendo un término que significa aferrarse a algo o a alguien con persistencia inquebrantable. En Hechos se convierte casi en un término técnico para la devoción comunitaria de la iglesia primitiva: ''perseveraban'' en la enseñanza de los apóstoles, la comunión, el partimiento del pan y las oraciones (Hch 2:42). Sin embargo, en dos pasajes el sentido se desplaza hacia la atención personal: en Marcos 3:9 Jesús pide que una barca ''esté dispuesta'' para él, y en Hechos 10:7 un soldado devoto de Cornelio le ''servía'' constantemente. La idea subyacente es siempre una presencia sostenida y confiable, ya sea dirigida a una práctica sagrada o a una persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4348', 'spa', 'proskomma — tropiezo, obstáculo o causa de ofensa espiritual', 'El sustantivo neutro proskomma (de προσκόπτω, ''golpear contra'') designa aquello que hace tropezar, caer o desviarse. En el Nuevo Testamento funciona casi exclusivamente en el registro metafórico-espiritual: Cristo es ''la piedra de tropiezo'' para el Israel incrédulo (Rom 9:32-33, citando Isa 8:14), y Pablo advierte a los creyentes que no pongan tropiezo ante un hermano más débil al ejercer su libertad descuidadamente (Rom 14:13, 20; 1 Cor 8:9). La imagen es vívida: una roca en el camino que atrapa al pie desprevenido. El español tropiezo conserva fielmente esa imaginería concreta y a la vez metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4350', 'spa', 'Tropezar, golpearse contra algo; literalmente de choque físico, figuradamente de ofensa espiritual o fracaso.', 'El verbo προσκόπτω evoca la imagen concreta de golpear el pie contra una piedra, imagen que el propio diablo cita del Salmo 91:12 al tentar a Jesús en el pináculo del templo (Mt 4:6; Lc 4:11). De esta raíz física brota un rico uso figurado: Israel ''tropezó'' con la piedra de tropiezo (Ro 9:32), se advierte a los creyentes que no hagan tropezar a un hermano (Ro 14:21), y caminar en tinieblas espirituales conduce al tropiezo (Jn 11:9-10). Las traducciones al español reflejan bien esta distinción: ''tropieces'' para el golpe físico y ''tropezaron'' para el sentido metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4352', 'spa', 'Postrarse en adoración ante Dios o en homenaje reverente ante una persona de autoridad; inclinarse, rendir pleitesía.', 'El verbo προσκυνέω recoge la práctica del antiguo Cercano Oriente y del mundo grecorromano de postrarse ante alguien de autoridad suprema. En el Nuevo Testamento abarca desde la adoración divina genuina, la que el Padre busca (Jn 4:23-24), hasta el homenaje reverente que los suplicantes rinden al caer a los pies de Jesús (Mat 8:2; 9:18). La línea entre estos sentidos es a menudo deliberadamente ambigua, pues quienes se postran ante Jesús pueden estar reconociendo más de lo que comprenden plenamente. El alemán anbeten y el español adorar se inclinan hacia el extremo de la adoración, mientras que el griego subyacente conserva el gesto físico de la postración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4355', 'spa', 'Tomar para sí: recibir en comunión, llevar aparte en privado, o tomar para uso personal (especialmente alimento).', 'Tomar para sí: recibir en comunión, llevar aparte en privado, o tomar para uso personal (especialmente alimento).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4357', 'spa', 'Permanecer con, quedarse, continuar; persistir en un lugar, con una persona o en una actividad o compromiso.', 'Verbo compuesto (πρός + μένω) que significa permanecer con alguien, quedarse o continuar con constancia. Aparece en dos contextos distintos: las multitudes que han «permanecido con» Jesús tres días sin comer (Mt 15:32; Mr 8:2), y la exhortación de la iglesia primitiva a perseverar en la fe y la comunidad. Bernabé insta a los creyentes en Antioquía a «permanecer con el Señor» con firme propósito de corazón (Hch 11:23), y Pablo y Silas se quedan en diversas ciudades (Hch 13:43; 18:18). Transmite continuidad fiel, no mera permanencia física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4363', 'spa', 'Postrarse ante alguien en súplica o adoración; caer sobre algo o golpear contra ello.', 'El verbo προσπίπτω significa literalmente ''caer hacia'' y en el Nuevo Testamento describe de manera predominante el acto de postrarse ante alguien en reverencia, súplica desesperada o adoración. Los espíritus inmundos caen ante Jesús proclamando su identidad (Mr 3:11), la mujer con flujo de sangre se postra ante él con temor y temblor (Mr 5:33), y una madre sirofenicia cae a sus pies suplicando la liberación de su hija (Mr 7:25). Una única aparición en Mateo 7:25 conserva el sentido más antiguo e impersonal de impacto físico: las lluvias y las aguas ''cayeron sobre'' la casa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4367', 'spa', 'Mandar, ordenar con autoridad; designar o disponer de antemano.', 'El verbo προστάσσω (de πρός + τάσσω, «disponer hacia») significa mandar u ordenar con autoridad. En el Nuevo Testamento aparece casi exclusivamente para directivas de Dios, Jesús o Moisés, con todo el peso de la autoridad divina o de la Torá. José obedece lo que el ángel le «mandó» (Mt 1:24), Jesús indica al leproso sanado que haga lo que Moisés «mandó» (Mt 8:4; Mr 1:44; Lc 5:14), y Cornelio envía a buscar a Pedro porque un ángel se lo «ordenó» (Hch 10:33). Un único caso en Hch 17:26 amplía el sentido de directiva verbal a designación soberana: Dios «señaló» los tiempos y los límites de las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4369', 'spa', 'Añadir o aumentar; también un hebraísmo que significa proceder o hacer algo más. προστίθημι es un verbo versátil cuyo sentido primario es simplemente ', 'Añadir o aumentar; también un hebraísmo que significa proceder o hacer algo más. προστίθημι es un verbo versátil cuyo sentido primario es simplemente añadir, ya sea algo a un grupo, una cantidad o una situación. El Señor ''añadía'' a la iglesia cada día los que iban siendo salvos (Hch 2:47), y Jesús enseña que buscando el reino de Dios todas las cosas os ''serán añadidas'' (Mt 6:33; Lc 12:31). Un sentido secundario distintivo refleja el hebraísmo de יָסַף, que significa ''proceder'' o ''volver a hacer,'' donde el verbo señala continuación en vez de aumento numérico. Lucas preserva este semitismo en Hechos 12:3, donde Herodes ''procedió a arrestar también a Pedro,'' una construcción que suena extraña en griego pero perfectamente natural en el estilo narrativo hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4370', 'spa', 'Correr hacia, acercarse corriendo; aproximarse rapidamente con proposito o entusiasmo', 'Este verbo significa correr hacia alguien, acercandose con rapidez y proposito. En el uso clasico incluia correr hacia personas o cosas, a veces con sentido hostil. En el Nuevo Testamento se emplea exclusivamente en los Evangelios para describir a personas que corren hacia Jesus con ansia, preguntas o necesidad. El termino capta tanto el movimiento fisico como la intensidad emocional del encuentro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4374', 'spa', 'Ofrecer un sacrificio o don; traer a alguien o algo ante otro; tratar, lidiar con.', 'Ofrecer un sacrificio o don; traer a alguien o algo ante otro; tratar, lidiar con.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4376', 'spa', 'Ofrenda o sacrificio presentado a Dios; tanto el acto de ofrecer como lo ofrecido, especialmente el autosacrificio de Cristo.', 'Designa una ofrenda o sacrificio religioso presentado ante Dios, abarcando tanto el acto de presentar como el don mismo. En Efesios 5:2, Cristo se entregó a sí mismo como ''ofrenda y sacrificio'', frase en la que este término acompaña al vocablo más general de sacrificio para subrayar el aspecto voluntario de la entrega. El autor de Hebreos lo emplea repetidamente para contrastar la ofrenda única y definitiva de Cristo con los sacrificios repetidos del antiguo pacto (Heb 10:5, 10, 14, 18). El español ''ofrenda'' conserva bien el sentido de un don traído ante la presencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4377', 'spa', 'Dirigirse a alguien de viva voz; llamar, interpelar o hablar directamente a una persona, ya sea para saludar, instruir o proclamar.', 'En el griego clásico, este verbo abarcaba una amplia gama de actos de habla directa, desde dirigirse a alguien por su nombre hasta dar órdenes. El Nuevo Testamento lo emplea tanto en escenas cotidianas —como cuando los niños se gritan unos a otros en la plaza (Mt 11:16; Lc 7:32)— como en momentos solemnes, como cuando Jesús llama a sus discípulos por nombre (Lc 6:13) o se dirige a una mujer encorvada en la sinagoga (Lc 13:12). El verbo siempre implica una comunicación deliberada y cara a cara, una interpelación personal que busca captar la atención del oyente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4382', 'spa', 'Acepción de personas, favoritismo; trato parcial basado en la apariencia externa o la condición social.', 'Sustantivo compuesto formado por πρόσωπον (rostro) y λαμβάνω (recibir), que literalmente significa «recibir el rostro», es decir, emitir juicios basados en la apariencia externa o la posición social de alguien. Cada aparición en el Nuevo Testamento condena esta práctica como incompatible con la justicia divina. Pablo declara que Dios no hace acepción de personas (Ro 2:11), y Santiago insiste en que el favoritismo hacia los ricos viola la ley real del amor (Stg 2:1). La expresión castellana «acepción de personas» conserva el modismo hebraico de «recibir rostros», mientras que el término «favoritismo» resalta directamente la violación ética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4383', 'spa', 'Rostro, semblante; por extensión, presencia, superficie o persona, reflejando la amplitud semítica del hebreo panim.', 'En el Nuevo Testamento, πρόσωπον lleva todo el peso de su equivalente hebreo פָּנִים (panim), significando mucho más que el simple rostro físico. Designa el semblante de una persona (Mat 17:2, donde el rostro de Jesús resplandeció como el sol), la presencia o ''faz'' de Dios (Hch 2:28) o la superficie frontal de algo (Lc 21:35, la faz de la tierra). El español rostro y el alemán Angesicht captan este sentido digno y relacional. En algunos pasajes, la palabra se desplaza por metonimia hacia ''persona'' o ''apariencia externa'', como cuando Pablo perdona ''en la persona de Cristo'' (2 Co 2:10), un uso que el francés personnes y el español personas hacen explícito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4384', 'spa', 'colocar delante, apostar al frente, asignar prioridad; situar tropas o clasificar cosas como previas o superiores', 'Este verbo de ámbito militar y organizativo significa colocar o apostar al frente, particularmente en contextos de formaciones de batalla donde las tropas se situaban delante de otras para protección o ataque. La voz media indicaba apostar las propias fuerzas hacia adelante. Más allá del posicionamiento literal, desarrolló el sentido de clasificar algo como previo o superior en importancia o secuencia. En documentos administrativos podía significar ''el susodicho'' o ''mencionado anteriormente''. La palabra refleja la preocupación griega por el orden adecuado, ya sea de soldados en formación o de conceptos en prioridad filosófica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4386', 'spa', 'Anterior, anteriormente, antes — indicando lo que ocurrió primero en el tiempo, ya sea como adjetivo o adverbio. La forma comparativa πρότερος (proter', 'Anterior, anteriormente, antes — indicando lo que ocurrió primero en el tiempo, ya sea como adjetivo o adverbio. La forma comparativa πρότερος (proteros) expresa prioridad temporal — ''anterior'' como adjetivo o ''anteriormente, antes'' como adverbio. Jesús pregunta a los discípulos: ''¿Y si vierais al Hijo del Hombre ascender a donde estaba antes?'' (Jn 6:62). Nicodemo es identificado como aquel que vino a Jesús ''anteriormente'' (Jn 7:50), y el hombre nacido ciego es reconocido por quienes lo veían ''antes'' como mendigo (Jn 9:8). Pablo relata que predicó en Galacia ''la primera vez'' (Gá 4:13), y Efesios 4:22 ordena despojarse de la ''antigua manera de vivir''. Hebreos 4:6 se refiere a quienes ''anteriormente'' recibieron las buenas nuevas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4387', 'spa', 'anterior, previo, primero; comparativos que indican lo que precede en tiempo, espacio o tiene precedencia', 'Estas formas comparativas y superlativas (πρότερος y πρῶτος), derivadas de πρό, indican relaciones de ''anterior'' frente a ''posterior''. Aunque ambas podían describir ubicación espacial (delante frente a detrás), su uso principal era temporal: tiempos pasados, generaciones anteriores, días previos o matrimonios precedentes. Las formas también portaban fuerza valorativa, señalando lo que tiene prioridad o viene primero en importancia. Homero las empleó para héroes de la antigüedad, mientras que los prosistas las usaron para marcar secuencias históricas. Las formas neutras podían funcionar adverbialmente, significando ''antes'' o ''anteriormente'', ayudando a los escritores griegos a establecer relaciones temporales claras en la narrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4388', 'spa', 'Poner delante, proponer, determinar; exhibir publicamente o predeterminar con proposito', 'Este verbo significa poner delante, proponer o determinar, ya sea presentando algo publicamente o decidiendo algo de antemano. En el uso clasico incluia servir alimentos, proponer ideas o planificar con anticipacion. Pablo lo emplea para describir tanto sus intenciones personales como los propositos eternos de Dios en Cristo. El termino conlleva connotaciones de declaracion publica deliberada o de un plan predeterminado conforme a la voluntad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4392', 'spa', 'Pretexto, excusa o razón aparente que se ofrece para justificar o encubrir los verdaderos motivos de una acción.', 'En el Nuevo Testamento, πρόφασις casi siempre conlleva un matiz negativo: una fachada falsa diseñada para enmascarar la codicia, el interés propio o la hostilidad. Jesús denuncia a los escribas que devoran las casas de las viudas ''como pretexto'' de largas oraciones (Mt 23:14; Mr 12:40; Lc 20:47), donde el español ''pretexto'' y el hindi ''bahane se'' acentúan el sentido de engaño deliberado. Sin embargo, en Juan 15:22 Jesús dice que el mundo ya no tiene ''excusa'' para su pecado, y aquí πρόφασις pasa de ser una razón fabricada a una justificación legítima que, de existir, podría realmente exonerar. Su rango semántico va desde el engaño manifiesto hasta la defensa genuina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4394', 'spa', 'Profecía: el don espiritual, el acto o el contenido de la declaración inspirada que revela la voluntad y los propósitos de Dios. En el griego bíblico,', 'Profecía: el don espiritual, el acto o el contenido de la declaración inspirada que revela la voluntad y los propósitos de Dios. En el griego bíblico, προφητεία abarca todo el fenómeno profético -- el don divino que capacita para hablar la palabra de Dios, el acto de entregar esa palabra, y el mensaje mismo. Pablo la clasifica entre los dones espirituales más elevados, instando a los corintios a buscarla por encima de las lenguas (1 Co 14:1). En Romanos 12:6 aparece como un carisma que debe ejercerse en proporción a la fe, mientras que en Apocalipsis enmarca todo el libro como testimonio profético. La palabra tiene peso en todas las lenguas: español profecía, francés prophétie, alemán Weissagung -- cada una preservando el doble sentido de predecir y proclamar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4395', 'spa', 'Profetizar; hablar o declarar bajo inspiración divina, ya sea prediciendo eventos futuros o proclamando la voluntad de Dios', 'Profetizar; hablar o declarar bajo inspiración divina, ya sea prediciendo eventos futuros o proclamando la voluntad de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4396', 'spa', 'Profeta — quien habla en nombre de Dios, transmitiendo mensajes, advertencias y promesas divinas al pueblo', 'Προφήτης en el griego clásico designaba a un intérprete o portavoz de una deidad, especialmente en los santuarios oraculares. El Nuevo Testamento hereda el uso de la Septuaginta para el hebreo נָבִיא, convirtiéndolo en el término estándar para quienes proclaman la palabra de Dios. Las 146 apariciones abarcan tres referentes principales: los profetas del Antiguo Testamento citados en fórmulas de cumplimiento (''lo dicho por medio del profeta'', Mt 2:17), Jesús mismo identificado como profeta (Mt 21:11; Lc 7:16) y los profetas neotestamentarios activos en las asambleas de la iglesia primitiva (1 Co 12:28; Ef 4:11). ''Profeta'' en español, ''prophete'' en francés y ''Prophet'' en alemán derivan todos de la misma raíz griega, preservando el sentido de portavoz divino autorizado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4400', 'spa', 'Designar de antemano, elegir previamente; seleccionar para un propósito específico determinado por Dios', 'Este verbo significa designar de antemano, elegir previamente o señalar para un propósito determinado. En el griego clásico se usaba para seleccionar líderes, movilizar tropas o escoger representantes. En el Nuevo Testamento, Lucas lo emplea exclusivamente en Hechos para describir la designación divina de Jesús o la elección de individuos por el Espíritu para el ministerio. El término subraya la selección soberana de Dios y su propósito predeterminado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4403', 'spa', 'Popa (de un barco); la parte trasera de una embarcación', 'Este término náutico designa la popa o parte trasera de un barco. El griego clásico lo empleaba ampliamente en contextos marítimos y navales, y a veces de forma metafórica para referirse a la parte posterior de cualquier cosa. El Nuevo Testamento lo usa literalmente en las narraciones a bordo de embarcaciones en Marcos y Hechos. Se trata de vocabulario náutico directo y concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4404', 'spa', 'πρωΐ -- temprano por la mañana, al amanecer; adverbio temporal que indica las primeras horas de luz del día.', 'πρωΐ -- temprano por la mañana, al amanecer; adverbio temporal que indica las primeras horas de luz del día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4410', 'spa', 'El asiento principal, el lugar de honor en una sinagoga o banquete; la posición más prestigiosa en una asamblea pública.', 'Sustantivo compuesto de πρῶτος (primero) y καθέδρα (asiento, silla), que designa el asiento más honorable en las asambleas públicas, especialmente en las sinagogas. Jesús señala repetidamente el amor por los «primeros asientos» como síntoma revelador de la vanidad religiosa de los escribas y fariseos (Mt 23:6; Mc 12:39; Lc 11:43; 20:46). El término refleja una práctica profundamente arraigada en la cultura del honor del Mediterráneo antiguo, donde la posición física al sentarse expresaba el rango social y religioso de la persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4411', 'spa', 'Lugar de honor en un banquete, asiento principal en la mesa; la posición más prestigiosa para reclinarse.', 'Sustantivo compuesto de πρῶτος (primero) + κλισία (lugar para reclinarse), que designa el asiento más honroso en la mesa de un banquete. Jesús critica reiteradamente a los fariseos y escribas por codiciar estos puestos: en Mat 23:6, Mar 12:39 y Luc 20:46 aparece junto a su afán por vestiduras largas y saludos en las plazas. Lucas 14:7-8 ofrece la parábola del banquete de bodas, donde los invitados se disputan el primer lugar arriesgándose a la humillación pública. En la disposición antigua del triclinio, ciertas posiciones reflejaban mayor estatus, y este término nombra precisamente la más codiciada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4412', 'spa', 'Primero, primeramente: adverbio de prioridad en tiempo, secuencia o importancia.', 'El adverbio griego πρῶτον (''primero'') señala prioridad temporal o lógica en el discurso. Jesús lo emplea reiteradamente para establecer lo que debe preceder a otra cosa: ''reconcíliate primero con tu hermano'' (Mat 5:24), ''buscad primero el reino de Dios'' (Mat 6:33), ''saca primero la viga de tu propio ojo'' (Mat 7:5). Pablo lo usa para la secuencia histórico-salvífica: ''al judío primero y también al griego'' (Ro 1:16). La palabra porta una fuerza retórica notable: lo que viene πρῶτον se presenta como innegociable, el paso previo necesario antes de que cualquier otra cosa pueda seguir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4413', 'spa', 'Primero en secuencia, tiempo o rango; persona principal o preeminente; por extensión, mejor en calidad o primero en prioridad lógica.', 'En el Nuevo Testamento, este adjetivo abarca un amplio espectro semántico enraizado en la idea de estar al frente. Con mayor frecuencia indica posición ordinal — el primer día, el primer pacto, el primer mandamiento — apareciendo unas 90 veces en ese sentido directo. Pero el griego πρῶτος también funciona como título de rango: los ''principales'' de una ciudad o los ciudadanos ''destacados'' (Marcos 6:21, Hechos 13:50). En una escena memorable, el padre pide el ''mejor'' vestido para el hijo pródigo (Lucas 15:22), donde el sentido se desplaza hacia un superlativo cualitativo distinto de la mera secuencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4416', 'spa', 'Primogenito: el primer hijo nacido, o figuradamente, quien ostenta rango supremo y preeminencia.', 'Prototokos abarca tanto un sentido literal de orden de nacimiento como una poderosa extension metaforica hacia la preeminencia divina. Lucas 2:7 lo emplea llanamente para referirse al primer hijo de Maria, mientras que Pablo en Colosenses 1:15 y 1:18 lo eleva a titulo cosmico: Cristo como ''primogenito de toda la creacion'' y ''primogenito de entre los muertos''. Hebreos 1:6 y 12:23 amplian el concepto aun mas: el Hijo introducido al mundo y la ''congregacion de los primogenitos'' inscritos en el cielo. Romanos 8:29 situa a los creyentes en relacion con este titulo, predestinados a ser conformados a la imagen del Hijo de Dios para que el fuese ''primogenito entre muchos hermanos''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4417', 'spa', 'Tropezar, dar un traspié, caer; fallar moral o espiritualmente, pecar o errar en la conducta.', 'Verbo que significa tropezar o dar un traspié, usado casi exclusivamente en el NT en su sentido metafórico de fracaso moral o espiritual. Romanos 11:11 plantea la pregunta decisiva: «¿Acaso tropezaron para caer sin remedio?», distinguiendo un tropiezo temporal de un colapso definitivo. Santiago emplea el término para subrayar la universalidad de la debilidad humana: «todos tropezamos de muchas maneras» (3:2), y quien guarda toda la ley pero tropieza en un solo punto se hace culpable de toda ella (2:10). El español «tropezar» conserva fielmente la imagen física del traspié detrás de la metáfora moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4420', 'spa', 'Ala; el ala de un ave o criatura alada, usada literal y figuradamente para la proteccion y el amparo divino.', 'Sustantivo que significa ala, derivado de πτερόν (pluma). En el NT aparece en dos contextos vividos. Jesus lamenta sobre Jerusalen: "Cuantas veces quise reunir a tus hijos, como la gallina reune a sus polluelos bajo sus alas" (Mt 23:37; Lc 13:34), una imagen de tierno amparo protector tomada del motivo veterotestamentario de las "alas de Dios". En Apocalipsis, las alas caracterizan a los cuatro seres vivientes (4:8, cada uno con seis alas) y al aguila grande cuyas alas llevan a la mujer a un lugar seguro (12:14). La metafora de proteccion y refugio bajo las alas es marcadamente semitica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4429', 'spa', 'Escupir, expulsar saliva de la boca; en el NT, asociado a las sanaciones de Jesús', 'Este verbo significa escupir o expulsar saliva de la boca. En el griego clásico se usaba tanto en sentido literal como en expresiones metafóricas de desprecio. Sin embargo, el Nuevo Testamento lo emplea exclusivamente en relatos de sanación donde Jesús utiliza la saliva como parte del proceso curativo. En lugar de expresar desprecio, el uso bíblico vincula la acción de escupir con el poder sanador y compasivo de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4430', 'spa', 'Cadáver, cuerpo muerto o sin vida; un cuerpo caído que yace inerte en el suelo.', 'Derivado del verbo πίπτω (caer), este sustantivo significa literalmente ''lo que ha caído'' y pasó a designar un cadáver o cuerpo sin vida. En el Nuevo Testamento aparece tanto en singular como en plural, siempre referido a un cuerpo humano muerto. Describe el cuerpo de Juan el Bautista reclamado por sus discípulos (Mt 14:12; Mr 6:29), el cadáver de Jesús solicitado por José de Arimatea (Mr 15:45) y los dos testigos dejados insepultos en Apocalipsis 11:8-9. El dicho proverbial sobre los buitres que se congregan ''donde está el cadáver'' (Mt 24:28) lo emplea con una imaginería sombría. Las traducciones son llamativamente uniformes: español ''cadáver'', francés ''cadavre'', alemán ''Leichnam''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4432', 'spa', 'Pobreza, mendicidad; estado de carecer de recursos materiales', 'Este sustantivo denota pobreza o mendicidad, la condición de carecer de recursos materiales. En el griego clásico se refería a la indigencia y la miseria extrema. Pablo lo usa en 2 Corintios para describir tanto la pobreza de los macedonios como la pobreza voluntaria de Cristo por nuestro bien. Apocalipsis lo emplea de manera irónica para describir a quienes se creen ricos pero en realidad son pobres. El término enfatiza la carencia material, a veces con profundo significado espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4434', 'spa', 'Pobre, indigente; persona reducida a la mendicidad, carente de recursos materiales o de autosuficiencia espiritual', 'Pobre, indigente; persona reducida a la mendicidad, carente de recursos materiales o de autosuficiencia espiritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4437', 'spa', 'Frecuente, repetido; que ocurre a menudo o a intervalos cercanos', 'Este adjetivo describe lo que es frecuente, repetido o que sucede a menudo. En el griego clásico podía referirse a cosas cercanas entre sí en espacio o tiempo. El Nuevo Testamento lo usa de manera adverbial para describir acciones repetidas: ayunos y oraciones frecuentes, visitas reiteradas y prácticas regulares. El término pone de relieve la regularidad y la repetición de una acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4439', 'spa', 'Puerta o portal, especialmente de una ciudad o del templo, como umbral de paso. Se refiere a una puerta grande o portal, típicamente de una ciudad o c', 'Puerta o portal, especialmente de una ciudad o del templo, como umbral de paso. Se refiere a una puerta grande o portal, típicamente de una ciudad o complejo del templo, que funciona como lugar de entrada, paso y encuentro público. En la enseñanza de Jesús, la puerta estrecha y la puerta ancha son metáforas del camino a la vida y el camino a la destrucción (Mt 7:13–14). Las puertas del Hades no prevalecerán contra la iglesia de Cristo (Mt 16:18). En Hechos, la Puerta Hermosa del templo es donde Pedro sana al hombre cojo (Hch 3:10), y la puerta de hierro de la ciudad se abre por sí sola para Pedro liberado (Hch 12:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4440', 'spa', 'Portal o entrada monumental; en Apocalipsis, las puertas de la Nueva Jerusalén celestial; en otros pasajes, una entrada o pórtico terrenal. En el grie', 'Portal o entrada monumental; en Apocalipsis, las puertas de la Nueva Jerusalén celestial; en otros pasajes, una entrada o pórtico terrenal. En el griego clásico, πυλών designaba una torre-puerta o garita separada del edificio que custodiaba. El Nuevo Testamento conserva tanto un uso escatológico grandioso como uno doméstico más humilde. Once de sus dieciocho apariciones se concentran en Apocalipsis 21-22, donde las doce puertas de la Nueva Jerusalén -- tres en cada lado -- definen la arquitectura de la ciudad celestial. Las siete restantes describen entradas terrenales ordinarias: el pórtico donde Pedro fue reconocido (Mt 26:71), la puerta donde yacía Lázaro (Lc 16:20), y la puerta de hierro que se abrió por sí sola para Pedro (Hch 12:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4441', 'spa', 'πυνθάνομαι -- indagar, preguntar, averiguar; buscar información mediante interrogación directa.', 'πυνθάνομαι -- indagar, preguntar, averiguar; buscar información mediante interrogación directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4442', 'spa', 'Fuego: combustion literal o fuego divino/escatologico de juicio, purificacion y teofania.', 'Πῦρ es el termino elemental para fuego en griego, cargado de enorme peso teologico en el Nuevo Testamento. Aparece en contextos literales cotidianos, como el fuego encendido para calentarse (Marcos 14:54; Lucas 22:55), pero con mucha mayor frecuencia en escenarios escatologicos y de juicio divino: el fuego inextinguible de la Gehena (Mateo 5:22; 18:8-9), el fuego que probara la obra de cada uno (1 Corintios 3:13-15) y el lago de fuego en Apocalipsis (Apocalipsis 20:14-15). El anuncio del Bautista de que el que viene bautizara «con Espiritu Santo y fuego» (Mateo 3:11) fusiona purificacion con juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4444', 'spa', 'Torre; estructura fortificada elevada usada para defensa, vigilancia o protección agrícola, como en una viña.', 'Uno de los términos arquitectónicos más versátiles del mundo antiguo, que designa cualquier estructura fortificada elevada, desde torres de vigilancia urbanas hasta las torres de piedra construidas en viñedos para protegerlos de ladrones y animales. Jesús emplea la torre del viñedo en la parábola de los labradores malvados (Mt 21:33; Mc 12:1), haciendo eco de Isaías 5:2, donde la torre simboliza el cuidado providencial de Dios para Israel. En Lucas, la torre aparece en dos contextos: el derrumbe de la torre de Siloé ilustra lo impredecible de la tragedia (Lc 13:4), y la torre sin terminar ilustra el costo del discipulado (Lc 14:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4446', 'spa', 'pyretos — fiebre; enfermedad caracterizada por temperatura corporal anormalmente elevada', 'Derivado de πῦρ (''fuego''), pyretos designa la fiebre como condición médica: un calor ardiente dentro del cuerpo. Las seis apariciones en el Nuevo Testamento se dan en relatos de sanación: Jesús sana a la suegra de Pedro de una fiebre severa (Mat 8:15; Mar 1:31; Luc 4:38-39), el hijo del oficial del rey yace enfermo con fiebre en Capernaúm (Juan 4:52) y el padre de Publio sufre de fiebre y disentería en Malta (Hch 28:8). La etimología conecta vívidamente el fuego con la enfermedad, reflejando la experiencia universal de la fiebre como un ardor interno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4448', 'spa', 'pyroō — arder con fuego; arder de pasión o angustia; refinar o purificar por fuego; incendiar', 'Pyroō extrae su fuerza de πῦρ (''fuego'') y abarca todo el espectro de los efectos del fuego: destructivo, purificador y pasional. Pablo lo emplea figuradamente para el ardor del deseo insatisfecho (1 Cor 7:9) y para la angustia del cuidado pastoral (2 Cor 11:29). En Apocalipsis adquiere una imagen metalúrgica: los pies de Cristo son como bronce ''refinado en un horno'' (Apoc 1:15), y él aconseja a Laodicea comprar oro ''refinado por fuego'' (Apoc 3:18). El uso escatológico en 2 Ped 3:12, donde los cielos ''son encendidos'', retorna al poder destructivo crudo del fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4450', 'spa', 'Rojo encendido, color de fuego; describe una apariencia rojiza o flamígera, como la del fuego o la sangre', 'Este adjetivo describe una apariencia roja encendida o del color de las llamas. En el griego clásico abarcaba tonalidades rojizo-amarillentas, especialmente cabello pelirrojo o animales de pelaje leonado. El Nuevo Testamento lo emplea una vez como nombre propio (Πύρρος) y dos veces en la imaginería apocalíptica de Apocalipsis para describir seres sobrenaturales. El término evoca el color del fuego y de la sangre, transmitiendo intensidad y poder en los contextos donde aparece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4451', 'spa', 'Incendio, prueba de fuego; el proceso de arder o de ser probado mediante el fuego', 'Este sustantivo designa la acción de arder o el proceso de ser probado por el fuego. En el uso clásico abarcaba desde la cocción literal y la cauterización hasta la prueba metafórica. El Nuevo Testamento lo emplea tanto en sentido literal para el fuego destructor como en sentido figurado para las pruebas ardientes que ponen a prueba la fe de los creyentes. Pedro y Juan lo utilizan en contextos de sufrimiento y juicio escatológico, donde el fuego purifica o consume.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4452', 'spa', 'aún, todavía, hasta ahora, en absoluto; partícula enclítica que expresa ''hasta este punto'' o ''alguna vez'' (generalmente con negaciones)', 'Esta partícula enclítica, que aparece como πω en griego ático y κω en jónico, significa ''aún'' o ''hasta este momento'' y casi siempre acompaña a negaciones en el griego temprano. La combinación οὔπω significa ''todavía no'', mientras que μήπω expresa ''todavía no'' en prohibiciones. En preguntas, podía significar ''alguna vez en absoluto'', como al inquirir si alguna ciudad había intentado algo. La partícula ayudaba a los hablantes griegos a marcar límites temporales, indicando que algo no había ocurrido hasta el momento presente pero aún podía suceder. Su alcance preciso la hacía especialmente útil en contextos filosóficos e históricos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4453', 'spa', 'Vender u ofrecer en venta; ser vendido (pasivo): intercambiar bienes o propiedades por dinero', 'Vender u ofrecer en venta; ser vendido (pasivo): intercambiar bienes o propiedades por dinero');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4454', 'spa', 'πῶλος -- pollino, burrito joven; el animal sin domar sobre el cual Jesús hizo su entrada triunfal.', 'πῶλος -- pollino, burrito joven; el animal sin domar sobre el cual Jesús hizo su entrada triunfal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4455', 'spa', 'pōpote — alguna vez hasta ahora; adverbio temporal usado con negación que significa ''jamás''', 'El adverbio pōpote (de πω ''todavía'' + ποτέ ''alguna vez'') significa ''alguna vez hasta ahora'' o ''en algún momento.'' En el Nuevo Testamento aparece exclusivamente con una negación precedente, formando el enfático ''jamás'' o ''nunca hasta ahora.'' Sus apariciones se agrupan en torno a declaraciones de unicidad o eventos sin precedente: ''a Dios nadie le vio jamás'' (Juan 1:18), ''nunca habéis oído la voz del Padre'' (Juan 5:37), ''el que cree en mí, no tendrá sed jamás'' (Juan 6:35), ''jamás hemos sido esclavos de nadie'' (Juan 8:33) y ''un pollino en el cual ningún hombre se ha sentado jamás'' (Luc 19:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4456', 'spa', 'Endurecer, hacer insensible; volver espiritualmente ciego o calloso, dicho del corazon y la mente resistentes a Dios.', 'Verbo derivado de πῶρος (piedra, deposito calcico) que significa petrificar o encallecer, producir una cobertura dura e insensible sobre el corazon o la mente. En el NT, todo uso es metaforico y teologico, describiendo el endurecimiento espiritual. Marcos registra dos veces el corazon endurecido de los discipulos a pesar de presenciar milagros (6:52; 8:17). Juan 12:40 cita Isaias 6:10 para explicar la incredulidad de Israel: Dios "les cego los ojos y les endureci el corazon". Romanos 11:7 y 2 Corintios 3:14 extienden este endurecimiento al ambito corporativo de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4457', 'spa', 'Dureza, endurecimiento; la condición endurecida u obstinada del corazón o la mente', 'Este término médico describía originalmente el callo que se forma cuando los huesos fracturados sanan. Metafóricamente, pasó a significar insensibilidad, ceguera u obstinación del corazón. El Nuevo Testamento lo emplea exclusivamente en este sentido figurado para describir la insensibilidad espiritual y la resistencia a la verdad de Dios. Subraya una condición endurecida que se resiste a la influencia divina, impidiendo la comprensión y la respuesta a la revelación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4458', 'spa', 'de algún modo, de alguna manera, en absoluto; adverbio enclítico que suaviza o matiza expresiones de modo', 'Este versátil adverbio enclítico de modo significa ''de algún modo'' o ''de alguna manera'', y con frecuencia suaviza la fuerza de otros adverbios o añade un matiz de aproximación. Se combinaba a menudo con negaciones para formar οὔπως (''de ningún modo'') y μήπως (''no sea que de alguna manera''). Cuando seguía a otros adverbios de modo como ''así'' o ''siempre'', resultaba casi intraducible pero aportaba un sentido griego de certeza matizada: ''de algún modo así'' o ''en cierta manera''. Esta partícula reflejaba la preocupación filosófica griega por la precisión, al tiempo que reconocía los límites de la descripción exacta. Hacía las afirmaciones menos absolutas y más sutiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4459', 'spa', 'Adverbio interrogativo e indefinido: ''¿cómo?'' en preguntas de modo o posibilidad; ''de algún modo, no sea que'' en cláusulas de aprensión.', 'Adverbio versátil que con mayor frecuencia introduce preguntas sobre el modo, el medio o la posibilidad — ''¿Cómo pueden ser estas cosas?'' (Juan 3:9). Cada lengua principal lo traduce con un interrogativo directo: español ''cómo,'' francés ''comment,'' alemán ''wie.'' En un conjunto más reducido pero teológicamente significativo de pasajes, se desplaza hacia un sentido indefinido que expresa aprensión o incertidumbre esperanzada — ''no sea que de algún modo'' o ''si acaso'' — como cuando Pablo confía en que su ministerio pueda ''de algún modo'' provocar a Israel a celos (Romanos 11:14). Las formas españolas ''acaso'' y ''de algún modo'' captan con precisión este matiz más suave e indefinido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4461', 'spa', 'Rabbí; título honorífico hebreo que significa ''mi maestro/mi señor'', usado como tratamiento respetuoso para instructores religiosos.', 'Rabbí; título honorífico hebreo que significa ''mi maestro/mi señor'', usado como tratamiento respetuoso para instructores religiosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4464', 'spa', 'ῥάβδος -- vara, bastón, cetro; palo recto usado para caminar, pastorear, disciplinar o como símbolo de autoridad real.', 'ῥάβδος -- vara, bastón, cetro; palo recto usado para caminar, pastorear, disciplinar o como símbolo de autoridad real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4472', 'spa', 'Rociar, especialmente con sangre o agua para purificación ritual; limpiar ceremonialmente.', 'Verbo de acción ritual arraigado en el sistema sacrificial levítico, donde la aspersión de sangre o agua efectuaba la purificación ceremonial. Las cuatro apariciones neotestamentarias se encuentran en Hebreos, donde el autor contrasta sistemáticamente los ritos de aspersión del antiguo pacto con la purificación superior realizada por la sangre de Cristo. La aspersión de sangre y agua por Moisés en el Sinaí (Heb 9:19, 21) y las cenizas de la vaca alazana (Heb 9:13) se presentan como sombras de la limpieza del corazón del creyente, rociado «de mala conciencia» (Heb 10:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4475', 'spa', 'Bofetada, golpe con la mano; especialmente un golpe en el rostro como insulto físico y social', 'Este sustantivo designa un golpe seco con la mano, generalmente en el rostro, un gesto que combina dolor físico y humillación social. Aparece en los relatos de la pasión: los guardias del templo abofetean a Jesús mientras se burlan de sus afirmaciones proféticas (Marcos 14:65), un siervo le da una bofetada durante el interrogatorio ante el sumo sacerdote (Juan 18:22), y los soldados romanos lo golpean como parte de su cruel teatro de escarnio (Juan 19:3). En estos contextos evangélicos, la violencia física es inseparable de la degradación social: cada bofetada expresa desprecio hacia las afirmaciones mesiánicas de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4483', 'spa', 'diré, yo diré; forma futura jónica del verbo ''decir'' (véase ἐρῶ)', 'Esta es simplemente la forma del dialecto jónico del tiempo futuro ''yo diré'', equivalente al ático ἐρῶ. Los dialectos griegos conservaron formas diferentes de verbos irregulares comunes, y ἐρέω representa la tradición jónica presente en Heródoto y otros escritores jonios. La forma en sí es directa: un tiempo futuro que llena un vacío en el verbo irregular ''decir''. Mientras que el griego ático se estandarizó en torno a ἐρῶ, el jónico mantuvo esta forma más antigua. Los diversos dialectos griegos preservaron tradiciones morfológicas alternativas que los gramáticos documentaron cuidadosamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4486', 'spa', 'Reventar o romper; arrojar violentamente al suelo; desgarrar o despedazar.', 'Un verbo de disrupción física violenta, ῥήγνυμι aparece en tres escenas evangélicas memorables. El vino nuevo revienta los odres viejos (Mt 9:17; Mr 2:22; Lc 5:37), donde el español ''romperá'' y ''se rompen'' captan la ruptura por presión interna. Los demonios se apoderan de un muchacho y ''lo derriban'' en convulsiones (Mr 9:18; Lc 9:42). Y los cerdos, al recibir las cosas santas, ''os despedazarán'' (Mt 7:6). En Gál 4:27, Pablo cita el llamado de Isaías a la mujer estéril a ''prorrumpir'' en gritos de alegría, el único uso no destructivo del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4487', 'spa', 'ῥῆμα: palabra hablada, declaracion o dicho; unidad discreta de habla que a menudo porta autoridad divina.', 'El sustantivo neutro ῥῆμα (''palabra, declaracion, dicho'') enfatiza el caracter oral de una palabra, algo pronunciado en voz alta, a diferencia de λόγος, que tiende mas hacia el contenido racional. En sus 69 apariciones neotestamentarias, ῥῆμα abarca desde lo cotidiano (''toda palabra ociosa'', Mateo 12:36) hasta lo revelatorio (''toda palabra que sale de la boca de Dios'', Mateo 4:4; cf. Deuteronomio 8:3). Es la espada del Espiritu (Efesios 6:17) y la palabra de fe que Pablo predica (Romanos 10:8). En espanol se traduce consistentemente como palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4491', 'spa', 'Raiz de una planta; en sentido figurado, origen, fuente o causa fundamental de algo. En su sentido mas basico, ῥίζα es la parte subterranea de una pla', 'Raiz de una planta; en sentido figurado, origen, fuente o causa fundamental de algo. En su sentido mas basico, ῥίζα es la parte subterranea de una planta que la ancla y la nutre. Sin embargo, el Nuevo Testamento explota ampliamente esta imagen en el lenguaje figurado. Juan el Bautista advierte que ''el hacha ya esta puesta a la raiz de los arboles'' (Mt 3:10; Lc 3:9), senalando un juicio divino inminente. La parabola del sembrador de Jesus describe la semilla que cae en terreno pedregoso sin raiz profunda (Mt 13:6, 21; Mc 4:6, 17). Pablo habla de la raiz de Isai (Ro 15:12) y advierte a los creyentes gentiles que ''la raiz te sostiene'' (Ro 11:16-18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4496', 'spa', 'Arrojar, lanzar o tirar con fuerza; echar al suelo, tirar a un lado o arrojar por la borda.', 'Un verbo enérgico de movimiento violento, ῥίπτω describe la acción de lanzar con fuerza o sin miramientos. Abarca diversas acciones físicas en el Nuevo Testamento: Judas arrojando las treinta monedas de plata en el templo (Mt 27:5), la gente echando a los enfermos a los pies de Jesús (Mt 15:30), un demonio tirando a un hombre al suelo (Lc 4:35) y la imagen de ser arrojado al mar con una piedra de molino (Lc 17:2). En Mateo 9:36, el participio perfecto pasivo se usa figuradamente para describir multitudes ''esparcidas'' como ovejas sin pastor, evocando agotamiento y desamparo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4501', 'spa', 'Espada grande y ancha; arma pesada usada literal y figuradamente para el dolor penetrante o el juicio divino.', 'A diferencia de la más común μάχαιρα (espada corta o daga), ῥομφαία designa una espada grande y pesada, originalmente asociada con los guerreros tracios. En el Nuevo Testamento posee tanto peso literal como profundamente simbólico. La profecía de Simeón de que «una espada traspasará tu propia alma» (Lucas 2:35) la emplea metafóricamente para el dolor venidero de María. En Apocalipsis aparece como la espada aguda de dos filos que sale de la boca de Cristo (Ap 1:16; 2:12, 16), simbolizando el juicio divino y el poder de la Palabra de Dios. También figura entre los instrumentos de muerte en la visión apocalíptica de Apocalipsis 6:8.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4505', 'spa', 'Calle estrecha, callejón o callejuela en una ciudad o pueblo.', 'Aunque en el griego clásico este término podía significar «ímpetu» o «fuerza», en el Nuevo Testamento y en el uso koiné posterior designa específicamente una calle angosta o callejuela dentro de una ciudad, distinta de la πλατεῖα (calle ancha) o la ὁδός (camino). Jesús contrasta la oración secreta con la ostentación pública «en las calles» (Mt 6:2), y el amo envía a sus siervos a los «callejones» para reunir a los marginados (Lc 14:21). En Hechos, el término nombra la calle llamada «Derecha» en Damasco (Hch 9:11) y la callejuela por la que Pedro caminó tras su liberación milagrosa de la prisión (Hch 12:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4506', 'spa', 'Rescatar, librar o arrastrar a lugar seguro; como sustantivo, ''el Libertador'', titulo de Dios o del Mesias. El verbo en voz media ῥύομαι transmite la ', 'Rescatar, librar o arrastrar a lugar seguro; como sustantivo, ''el Libertador'', titulo de Dios o del Mesias. El verbo en voz media ῥύομαι transmite la imagen vivida de arrebatar a alguien del peligro. Aparece en contextos que van desde la peticion del Padrenuestro de ser librados del mal (Mt 6:13) hasta el testimonio de Pablo de haber sido rescatado de peligro mortal (2 Co 1:10). Dos usos se distinguen especialmente: el participio sustantivado ὁ ῥυόμενος, ''el Libertador'', aplicado al Redentor que viene de Sion (Ro 11:26) y a Jesus que nos rescata de la ira venidera (1 Ts 1:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4511', 'spa', 'Flujo, derrame; la emisión o salida de un líquido, especialmente un flujo de sangre', 'Este sustantivo designa un flujo o derrame, particularmente de fluidos corporales. En el uso clásico abarcaba corrientes de río, mareas, rendimientos de aceite y afecciones médicas con descargas anormales. El Nuevo Testamento lo emplea exclusivamente para referirse a la hemorragia crónica de una mujer, una condición tanto médica como de impureza ritual que los Evangelios tratan con compasión. El término es clínico y descriptivo, y subraya la gravedad de una dolencia prolongada durante doce años.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4514', 'spa', 'Ῥωμαῖος -- romano; ciudadano o súbdito de Roma, usado como adjetivo y sustantivo.', 'Ῥωμαῖος -- romano; ciudadano o súbdito de Roma, usado como adjetivo y sustantivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4516', 'spa', 'Roma: la ciudad capital del Imperio Romano, centro del poder imperial y de la primitiva comunidad cristiana.', 'El nombre propio Roma (Rhome) aparece ocho veces en el NT, siempre designando la capital imperial. Funciona como destino geografico y como simbolo teologico. Hechos traza el viaje divinamente ordenado de Pablo hacia Roma (Hechos 19:21; 23:11 — ''es necesario que testifiques tambien en Roma''), culminando en su llegada y arresto domiciliario (Hechos 28:14-16). Romanos 1:7 se dirige a los santos ''en Roma'', y Hechos 18:2 menciona la expulsion de Aquila y Priscila de la ciudad bajo Claudio. En practicamente todos los idiomas el nombre se conserva casi sin cambios, testimonio de la perdurable huella cultural de la ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4521', 'spa', 'El sabado, septimo dia de descanso y adoracion; por extension, la semana como unidad de siete dias contada de sabado a sabado.', 'Tomado del hebreo שַׁבָּת al griego como σάββατον, este termino satura los relatos evangelicos con controversias sobre la observancia correcta del sabado. Jesus sana en sabado (Mateo 12:10), sus discipulos arrancan espigas (Mateo 12:1-2) y el dia mismo se convierte en campo de batalla para la interpretacion de la Tora. En un uso secundario, σάββατον se extiende para significar la semana entera: ''el primer dia del σάββατον'' (Marcos 16:2; Lucas 24:1; Juan 20:1) se refiere al domingo, el dia despues del sabado. En espanol la distincion entre ''sabado'' (el dia) y ''semana'' (el periodo) hace especialmente visible este desplazamiento semantico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4523', 'spa', 'Saduceo -- miembro de la secta judía aristocrático-sacerdotal que negaba la resurrección y los espíritus angélicos.', 'Saduceo -- miembro de la secta judía aristocrático-sacerdotal que negaba la resurrección y los espíritus angélicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4526', 'spa', 'Cilicio; tela áspera de pelo de cabra usada como señal de duelo, arrepentimiento o aflicción profunda.', 'Préstamo del hebreo/arameo (שַׂק), este término designa el tejido tosco y oscuro elaborado con pelo de cabra o camello que se convirtió en el símbolo bíblico universal de duelo, luto y penitencia. Jesús lo invoca en su reprensión contra Corazín y Betsaida, declarando que Tiro y Sidón se habrían arrepentido hace tiempo «en cilicio y ceniza» (Mt 11:21; Lc 10:13). En Apocalipsis, el sol se vuelve «negro como cilicio» al abrirse el sexto sello (Ap 6:12), y los dos testigos de Dios profetizan vestidos de cilicio (Ap 11:3). El término español «cilicio» enfatiza la función penitencial de la prenda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4528', 'spa', 'Salatiel (hebreo: ''pedí a Dios''); padre de Zorobabel en la genealogía de Jesús', 'Salatiel es la forma griega del nombre hebreo que significa ''pedí a Dios''. Aparece en las genealogías de Jesús como padre de Zorobabel, el gobernador postexílico que dirigió el regreso de Babilonia y la reconstrucción del templo. Su nombre vincula el linaje de Jesús con el período de restauración posterior al exilio, subrayando la fidelidad de Dios en cumplir sus promesas a través de las generaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4531', 'spa', 'Sacudir, agitar o hacer tambalear; se usa para terremotos, conmociones cósmicas, agitación de multitudes y perturbación interior del ánimo. Este verbo', 'Sacudir, agitar o hacer tambalear; se usa para terremotos, conmociones cósmicas, agitación de multitudes y perturbación interior del ánimo. Este verbo abarca todo el espectro del sacudimiento: desde el temblor literal del cielo y la tierra hasta la desestabilización figurada de la serenidad de una persona. Jesús pregunta a las multitudes qué salieron a ver: ''¿Una caña sacudida por el viento?'' (Mt 11:7; Lc 7:24), y los discursos apocalípticos advierten que ''las potencias de los cielos serán sacudidas'' (Mt 24:29; Mc 13:25). Pablo lo emplea para la estabilidad interior al exhortar a los tesalonicenses a no ''ser sacudidos en mente'' (2 Ts 2:2). Un uso concreto y encantador describe el grano siendo ''sacudido junto'' para asentar una medida generosa (Lc 6:38).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4536', 'spa', 'Trompeta — instrumento de viento metálico usado para señales militares, convocatoria de adoración y anuncio escatológico. El sustantivo σάλπιγξ (salpi', 'Trompeta — instrumento de viento metálico usado para señales militares, convocatoria de adoración y anuncio escatológico. El sustantivo σάλπιγξ (salpinx) designa tanto el instrumento como su sonido. En contextos escatológicos anuncia la reunión final: los ángeles reunirán a los elegidos ''con gran sonido de trompeta'' (Mt 24:31), los muertos en Cristo resucitarán a la ''última trompeta'' (1 Co 15:52) y el Señor descenderá ''con trompeta de Dios'' (1 Ts 4:16). Apocalipsis se abre con Juan oyendo una voz ''como de trompeta'' (Ap 1:10) y despliega los siete juicios de las trompetas (Ap 8–11). Pablo también la emplea de manera práctica: ''Si la trompeta da un sonido incierto, ¿quién se preparará para la batalla?'' (1 Co 14:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4537', 'spa', 'σαλπίζω (salpizō) — tocar la trompeta, dar un toque de trompeta; usado en contextos apocalípticos, litúrgicos y figurados. Este verbo designa la acció', 'σαλπίζω (salpizō) — tocar la trompeta, dar un toque de trompeta; usado en contextos apocalípticos, litúrgicos y figurados. Este verbo designa la acción de soplar una trompeta o cuerno. Su uso en el Nuevo Testamento está dominado por los siete ángeles del Apocalipsis, cada uno de los cuales toca una trompeta para inaugurar juicios sucesivos sobre la tierra (Ap 8:6-13; 9:1, 13; 10:7; 11:15). Pablo lo emplea escatológicamente para la última trompeta que señala la resurrección: ''la trompeta sonará, y los muertos serán resucitados incorruptibles'' (1 Co 15:52). Jesús lo usa con mordaz ironía en el Sermón del Monte, advirtiendo a los hipócritas que no toquen trompeta cuando den limosna (Mt 6:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4540', 'spa', 'Samaria — la región y ciudad principal en el centro de Palestina entre Judea y Galilea, tierra natal de los samaritanos. El nombre propio Σαμάρεια (Sa', 'Samaria — la región y ciudad principal en el centro de Palestina entre Judea y Galilea, tierra natal de los samaritanos. El nombre propio Σαμάρεια (Samareia) designa tanto la antigua ciudad como la región más amplia de la Palestina central entre Judea y Galilea. En Juan 4:4-7, Jesús pasa ''por Samaria'' y se encuentra con la mujer samaritana junto al pozo de Jacob. Lucas 17:11 sitúa a Jesús ''entre Samaria y Galilea''. El Cristo resucitado comisiona a los discípulos como testigos ''en Jerusalén, en toda Judea y Samaria, y hasta lo último de la tierra'' (Hch 1:8), y Hechos registra la expansión del evangelio en Samaria mediante la predicación de Felipe (Hch 8:1-14) y la paz de la iglesia ''por toda Judea, Galilea y Samaria'' (Hch 9:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4541', 'spa', 'Samaritano: persona de la region de Samaria, considerada por los judios como etnica y religiosamente distinta.', 'Identifica a una persona de Samaria, la region entre Judea y Galilea cuyos habitantes eran considerados por los judios como religiosamente comprometidos y etnicamente mestizos debido al reasentamiento asirio siglos antes. Las interacciones de Jesus con los samaritanos figuran entre los momentos mas transgresores de los Evangelios: la parabola del Buen Samaritano (Lucas 10:33), el leproso samaritano agradecido (Lucas 17:16) y la extensa conversacion junto al pozo de Jacob (Juan 4:9, 39, 40). El termino lleva una enorme carga social — ''los judios no se tratan con los samaritanos'' (Juan 4:9) — lo que convierte cada mencion positiva en un desafio deliberado a la exclusion etnica y religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4545', 'spa', 'Samuel (hebreo: ''escuchado por Dios''); profeta y juez que ungió a los primeros reyes de Israel', 'Samuel es la forma griega del nombre hebreo que significa ''escuchado por Dios'' o ''nombre de Dios''. Fue el último juez de Israel y el profeta que ungió tanto a Saúl como a David como reyes. El Nuevo Testamento lo menciona como una figura profética clave que anunció la era mesiánica y como ejemplo destacado de fe. Su ministerio marca la transición entre la época de los jueces y la monarquía israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4549', 'spa', 'Saul: nombre hebreo (Sha''ul, ''pedido [a Dios]'') usado para el rey Saul y la identidad previa a la conversion de Pablo.', 'Transliteracion griega del nombre hebreo Sha''ul, que significa ''pedido'' o ''solicitado'', reflejando la oracion de quien pidio un hijo a Dios. En el Nuevo Testamento se refiere tanto al rey Saul de Israel (Hechos 13:21) como, de manera mas prominente, a Saulo de Tarso antes de su conversion en el apostol Pablo. Cristo resucitado lo llama por este nombre en el camino a Damasco: ''Saulo, Saulo, ¿por que me persigues?'' (Hechos 9:4; 22:7). La forma griega Saoul preserva la ortografia septuagintal, mientras que en espanol se ha consolidado como ''Saul''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4550', 'spa', 'Podrido, malo, inutil: describe algo deteriorado en calidad o no apto para su uso.', 'Originalmente describe la putrefaccion fisica — fruta podrida, pescado pasado, madera carcomida — pero sapros adquiere un sentido moral y cualitativo en la ensenanza de Jesus. En la metafora del arbol y su fruto (Mateo 7:17-18; 12:33), un arbol ''malo'' no puede producir buen fruto. En la parabola de la red (Mateo 13:48), los peces ''malos'' son separados y desechados. Efesios 4:29 aplica el termino al habla: ninguna palabra ''corrompida'' debe salir de vuestra boca. La trayectoria de lo fisico a lo moral es notablemente consistente a lo largo del NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4554', 'spa', 'Sardis; antigua ciudad rica de Asia Menor, sede de una de las siete iglesias del Apocalipsis', 'Sardis fue la antigua capital de Lidia en el oeste de Asia Menor, famosa por su riqueza, su acrópolis fortificada y su posterior declive. En tiempos del Nuevo Testamento ya había pasado su época de esplendor, pero aún conservaba importancia. Fue una de las siete iglesias a las que se dirige el Apocalipsis, reprendida por estar espiritualmente muerta a pesar de tener fama de estar viva, una advertencia solemne contra la complacencia espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4555', 'spa', 'sardio, piedra sardiana; gema de color rojo parduzco o rojo, variedad de cornalina o sardónice', 'Esta palabra designa la piedra sardiana, una gema que recibe su nombre de Sardis en Asia Menor. Las fuentes antiguas distinguían dos variedades: la piedra ''femenina'', roja y transparente (nuestra cornalina), y la piedra ''masculina'', parda y transparente (nuestro sardio). Griegos y romanos apreciaban estas piedras para sellos y ornamentos. La piedra aparece en descripciones bíblicas de las vestiduras sacerdotales y en visiones apocalípticas, donde su intenso color rojo tenía un peso simbólico. Los escritores griegos posteriores emplearon diversas formas como σάρδιος, σάρδινος y σαρδόνιον para referirse a este preciado material, que adornó objetos tanto sagrados como seculares a lo largo de la antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4559', 'spa', 'Carnal, de la carne; relativo a la naturaleza humana sin el Espíritu, o hecho de carne en contraste con lo espiritual.', 'Este adjetivo describe lo que pertenece a o se caracteriza por σάρξ (carne). Pablo lo usa de manera prominente al contrastar las realidades espirituales con las materiales. En 1 Corintios 3:1-3 reprende a los creyentes por ser σαρκίνοι —gobernados por impulsos carnales como los celos y las contiendas en lugar del Espíritu. Sin embargo, el término no siempre es peyorativo: en Romanos 15:27 y 1 Corintios 9:11 simplemente describe provisiones materiales —«cosas carnales» como el sustento económico— que son la contrapartida natural de las bendiciones espirituales. En 2 Corintios 1:12, Pablo contrasta la sabiduría carnal con la gracia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4560', 'spa', 'Hecho de carne, carnal; relativo a la naturaleza humana en su debilidad o condición física y mortal.', 'Adjetivo derivado de σάρξ (carne) con el sufijo -ινος que indica composición material: literalmente ''hecho de carne''. Pablo lo emplea para describir la condición humana en su fragilidad mortal: vendida bajo el pecado (Rom 7:14), espiritualmente inmadura (1 Cor 3:1), pero también como medio vivo sobre el cual Dios escribe su nuevo pacto — ''tablas de carne'' en lugar de piedra (2 Cor 3:3). Hebreos contrasta un ''mandamiento carnal'' con el poder de una vida indestructible (Heb 7:16). A diferencia del más éticamente cargado σαρκικός, este término subraya la composición material del ser humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4561', 'spa', 'Carne — la sustancia material del cuerpo; por extensión, la naturaleza humana, la fragilidad mortal y la vida al margen del Espíritu.', 'σάρξ recorre un arco semántico notable en el Nuevo Testamento: desde el tejido literal del cuerpo (''los dos serán una sola carne,'' Mateo 19:5) hasta toda la esfera de debilidad creatural y vulnerabilidad moral (''el espíritu está dispuesto, pero la carne es débil,'' Mateo 26:41). Pablo agudiza este uso, empleando σάρξ para la condición humana no redimida opuesta al Espíritu (Romanos 8:4-9; Gálatas 5:16-17). Sin embargo, la palabra nunca se vuelve puramente negativa — la encarnación misma se expresa en términos de carne (Juan 1:14; 1 Timoteo 3:16). Las 150 ocurrencias se agrupan bajo un amplio gradiente conceptual entre lo literal y lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4563', 'spa', 'Barrer, limpiar barriendo; quitar suciedad o escombros con una escoba', 'Este verbo significa barrer o limpiar barriendo, eliminando suciedad y residuos. En el griego clásico se refería a la limpieza doméstica común. En el Nuevo Testamento aparece en las enseñanzas de Jesús con connotaciones espirituales: tanto en la parábola del demonio que regresa a la casa barrida y ordenada como en la parábola de la mujer que barre la casa buscando su moneda perdida. El término combina la acción literal de limpiar con profundas implicaciones espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4564', 'spa', 'Sara; esposa de Abraham, madre de Isaac y matriarca del pueblo del pacto de Israel.', 'Forma griega del nombre hebreo שָׂרָה (originalmente שָׂרַי, renombrada en Gn 17:15), que significa ''princesa''. En el Nuevo Testamento, Sara aparece como modelo de fe y promesa del pacto. Pablo la cita en Romanos para demostrar que la promesa de Dios opera por poder sobrenatural y no por capacidad natural: Abraham no vaciló a pesar de la esterilidad de Sara (Rom 4:19), y ''por medio de Sara'' vino la palabra de promesa (Rom 9:9). Hebreos celebra su fe al concebir a Isaac más allá de la edad fértil (Heb 11:11), y Pedro la presenta como ejemplo de conducta santa y confianza serena para las esposas creyentes (1 Pe 3:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4566', 'spa', 'Satanás, el Adversario; préstamo del hebreo para el jefe de los espíritus malignos, el Diablo, el oponente de Dios', 'Este es una transliteración de la palabra hebrea que significa ''adversario'' u ''oponente'', que la Septuaginta a veces tradujo con equivalentes griegos como ἐπίβουλος (''conspirador'') o διάβολος (''acusador''). En el uso judío y cristiano, se convirtió en el nombre propio del jefe de los espíritus malignos que se opone a Dios y acusa a la humanidad. La palabra podía permanecer indeclinable o adoptar la terminación griega -ᾶς para formar Σατανᾶς. Los autores del Nuevo Testamento la emplearon extensamente para referirse al ser espiritual personal que tienta, engaña y busca frustrar los propósitos de Dios. El nombre encapsula el concepto teológico de la oposición cósmica a la voluntad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4567', 'spa', 'Satanás, el Adversario; el principal enemigo espiritual y acusador en la teología bíblica', 'Satanás, el Adversario; el principal enemigo espiritual y acusador en la teología bíblica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4569', 'spa', 'Saulo (Σαῦλος) — el nombre judío del apóstol Pablo antes y durante su ministerio temprano. Forma helenizada del nombre hebreo שָׁאוּל (Sha''ul, ''pedido', 'Saulo (Σαῦλος) — el nombre judío del apóstol Pablo antes y durante su ministerio temprano. Forma helenizada del nombre hebreo שָׁאוּל (Sha''ul, ''pedido'' o ''solicitado en oración''), usada en Hechos para el apóstol Pablo durante su vida antes de la conversión y los primeros años de su ministerio. Lucas lo presenta como un joven que consentía la ejecución de Esteban (Hch 7:58; 8:1) y luego como un feroz perseguidor de la iglesia (Hch 8:3; 9:1). La dramática conversión en el camino a Damasco se narra bajo este nombre — ''Saulo, Saulo, ¿por qué me persigues?'' (Hch 9:4) — y Lucas continúa usando Saulos hasta el encuentro con Bar-Jesús en Chipre, tras lo cual el nombre Pablo (Παῦλος) toma el relevo (Hch 13:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4570', 'spa', 'Apagar, extinguir: sofocar fuego o luz, o figuradamente suprimir la obra del Espíritu.', 'Σβέννυμι significa apagar o extinguir una llama, y el NT lo emplea tanto en sentido literal como figurado con notable efecto. Jesús cita a Isaías: «la mecha humeante no apagará» (Mt 12:20), evocando la delicada preservación de lo débil. Las vírgenes insensatas claman que sus lámparas «se apagan» (Mt 25:8). Marcos 9:44-48 repite el terrible estribillo sobre la Gehenna donde «el fuego no se apaga». La orden de Pablo «no apaguéis al Espíritu» (1 Ts 5:19) transfiere la metáfora del fuego a la actividad del Espíritu Santo. Hebreos 11:34 celebra a quienes «apagaron la fuerza del fuego».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4571', 'spa', 'tú (singular); pronombre personal de segunda persona singular en caso acusativo (σε)', 'Este es el pronombre personal de segunda persona singular «tú», que refleja la rica variación dialectal del griego antiguo. Las formas variaban considerablemente según el dialecto: el ático usaba σύ (nominativo) y σοῦ (genitivo), mientras que el épico y el jónico conservaban formas como τύνη, σεο y τεῦ. El acusativo σε es una de las formas más frecuentes en el griego del Nuevo Testamento. El griego antiguo distinguía cuidadosamente entre el singular y el plural de la segunda persona, lo cual hacía de estas formas singulares un recurso fundamental para indicar un trato personal directo con un individuo. Estos pronombres tenían un peso especial en la oración, los mandamientos y la confrontación personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4572', 'spa', 'Ti mismo, a ti mismo — pronombre reflexivo de segunda persona singular que indica que el sujeto actúa sobre sí mismo', 'Ti mismo, a ti mismo — pronombre reflexivo de segunda persona singular que indica que el sujeto actúa sobre sí mismo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4575', 'spa', 'Augusto, venerable; digno de reverencia, especialmente como título de los emperadores romanos', 'Este adjetivo significa venerable, augusto o digno de reverencia. En el griego clásico se aplicaba a personas y cosas veneradas. Durante el período imperial romano se convirtió en el equivalente griego del latín ''Augustus'', el título de los emperadores romanos. Lucas lo emplea exclusivamente en este sentido imperial para referirse al César y a lo asociado con su autoridad, como la Cohorte Augusta mencionada en Hechos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4576', 'spa', 'Adorar, venerar o mostrar devoción piadosa — frecuentemente referido a gentiles temerosos de Dios atraídos al judaísmo. Verbo que denota adoración rev', 'Adorar, venerar o mostrar devoción piadosa — frecuentemente referido a gentiles temerosos de Dios atraídos al judaísmo. Verbo que denota adoración reverente o devoción religiosa, y que aparece de manera más característica en Hechos para describir a los gentiles temerosos de Dios que adoraban al Dios de Israel sin una conversión plena como prosélitos. Lidia es una σεβομένη, adoradora de Dios, cuando Pablo la encuentra en Filipos (Hch 16:14). Pablo regularmente se dirige a audiencias de sinagoga que incluyen σεβόμενοι junto con judíos (Hch 13:43, 50; 17:4, 17). En los Evangelios, Jesús cita la reprensión de Isaías: ''En vano me adoran'' (Mt 15:9; Mr 7:7). El término abarca así tanto la adoración auténtica como la deficiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4578', 'spa', 'Terremoto o sacudida violenta; se usa para eventos sísmicos y, por extensión, una tempestad feroz en el mar. Derivado del verbo σείω (''sacudir''), σεισ', 'Terremoto o sacudida violenta; se usa para eventos sísmicos y, por extensión, una tempestad feroz en el mar. Derivado del verbo σείω (''sacudir''), σεισμός se refiere más comúnmente a un terremoto, un temblor literal de la tierra. En los Evangelios marca momentos de significación divina: la tierra tiembla en la crucifixión (Mt 27:54), al rodar la piedra del sepulcro (Mt 28:2) y en el discurso profético de Jesús sobre los últimos días (Mt 24:7). En un caso notable (Mt 8:24), la palabra describe una tormenta violenta en el mar de Galilea, extendiendo la imagen de sacudida de la tierra al agua — un uso que las traducciones multilingües luchan por captar, recurriendo a menudo a ''terremoto'' incluso donde ''tempestad'' encaja mejor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4579', 'spa', 'Sacudir, hacer temblar; agitar fisicamente (como en un terremoto) o conmover emocionalmente con temor o asombro.', 'Verbo que significa sacudir o hacer temblar, usado tanto para la agitacion fisica como la emocional. Cuando Jesus entro en Jerusalen, "toda la ciudad se conmovio" (ἐσείσθη, Mt 21:10), con una ambiguedad deliberada entre temblor real y conmocion publica. En la crucifixion, la tierra temblo y las rocas se partieron (Mt 27:51). En la resurreccion, los guardias temblaron de miedo y quedaron como muertos (Mt 28:4). Hebreos 12:26 cita la profecia de Hageo sobre una sacudida cosmica final. El griego mantiene unidos los planos fisico y emocional que el castellano distribuye entre "sacudir", "temblar" y "conmover".');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4582', 'spa', 'La luna; el cuerpo lunar como objeto celeste, frecuentemente emparejado con el sol en la imaginería escatológica o cósmica.', 'Σελήνη designa la luna, una de las grandes luminarias del orden creado. En el Nuevo Testamento aparece casi exclusivamente en contextos apocalípticos o cosmológicos: la luna no dará su luz al final de los tiempos (Mt 24:29; Mr 13:24), se convertirá en sangre antes del día del Señor (Hch 2:20) y posee su propia gloria distintiva entre los cuerpos celestes (1 Co 15:41). El término español «luna» refleja un sentido único y unificado, sin extensión metafórica en el corpus neotestamentario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4586', 'spa', 'Digno de respeto; decoroso, noble, honorable — que inspira admiración reverente por su gravedad moral.', 'Derivado del verbo σέβομαι (''reverenciar''), este adjetivo describe personas o cosas que inspiran un respeto solemne. En el griego clásico se reservaba para dioses y ritos sagrados, pero el Nuevo Testamento lo aplica a la conducta cotidiana de los creyentes. Pablo lo coloca junto a palabras como ''verdadero'', ''justo'' y ''puro'' en Filipenses 4:8, trazando el retrato de una mente digna de meditación. En las Epístolas Pastorales define el carácter esperado de los diáconos (1 Ti 3:8), sus esposas (1 Ti 3:11) y los hombres mayores (Tit 2:2) — no una formalidad rígida, sino una vida que naturalmente atrae honra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4587', 'spa', 'dignidad, seriedad; cualidad de ser honorable, grave y digno de respeto', 'Este sustantivo designa la dignidad, seriedad o gravedad: la cualidad de ser honorable y digno de respeto. En el uso clásico incluía solemnidad y compostura. Las Epístolas Pastorales lo emplean exclusivamente para describir el comportamiento esperado de los líderes de la iglesia y el ambiente de las reuniones cristianas. El término enfatiza una conducta visiblemente respetable y decorosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4591', 'spa', 'sēmainō — significar, indicar o dar a conocer mediante señales o comunicación simbólica', 'El verbo sēmainō (de σῆμα, ''señal'') significa indicar o dar a conocer mediante señales, signos o lenguaje simbólico. En el Evangelio de Juan describe cómo Jesús ''dio a entender'' la manera de su muerte (Juan 12:33; 18:32) y la de Pedro (Juan 21:19), usando un habla indirecta y profética en lugar de una declaración llana. En Hechos, el profeta Ágabo ''dio a entender'' una hambruna venidera por medio del Espíritu (Hch 11:28), y en Apocalipsis 1:1, Dios ''dio a conocer'' la visión apocalíptica a Juan a través de un ángel. El término conlleva connotaciones de comunicación indirecta, mediada o simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4592', 'spa', 'Senal, senal milagrosa; un signo visible o prodigio que autentica la autoridad divina o el mensaje profetico.', 'El griego σημεῖον designa un indicador visible o marca autenticadora, y en el Nuevo Testamento se refiere de manera abrumadora a senales milagrosas que revelan el poder y proposito divinos. Los fariseos exigen repetidamente ''una senal del cielo'' (Mateo 12:38; 16:1), mientras que el Evangelio de Juan estructura su narrativa en torno a siete σημεῖα que manifiestan la identidad de Jesus. Pablo distingue ''senales y prodigios'' como credenciales apostolicas (2 Corintios 12:12), y el discurso escatologico advierte sobre senales falsas (Mateo 24:24). La palabra tiende un puente entre evidencia y asombro: un σημεῖον nunca es mero espectaculo, sino que siempre apunta mas alla de si mismo hacia la autoridad de quien lo realiza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4594', 'spa', 'Hoy, este mismo día — adverbio que señala el día presente, frecuentemente con fuerza teológica de inmediatez divina', 'Hoy, este mismo día — adverbio que señala el día presente, frecuentemente con fuerza teológica de inmediatez divina');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4597', 'spa', 'polilla; insecto que consume y destruye telas y materiales almacenados', 'Este sustantivo designa la polilla, el insecto conocido por consumir telas y materiales almacenados. La literatura clásica lo empleaba tanto en sentido literal como metafórico para referirse a agentes de destrucción. Jesús lo utiliza en su enseñanza sobre los tesoros terrenales frente a los celestiales, donde la polilla y el óxido representan la inevitable decadencia de las riquezas materiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4601', 'spa', 'Callar, guardar silencio o dejar de hablar; también guardar algo en secreto u oculto en silencio. σιγάω proviene de σιγή (''silencio'') y en nueve de su', 'Callar, guardar silencio o dejar de hablar; también guardar algo en secreto u oculto en silencio. σιγάω proviene de σιγή (''silencio'') y en nueve de sus diez usos en el NT simplemente significa quedarse callado o abstenerse de hablar, ya sea por decisión propia o por mandato. Después de la Transfiguración, los discípulos ''callaron'' y no dijeron nada a nadie (Lc 9:36); la multitud intentó hacer callar al ciego, pero él gritaba aún más fuerte (Lc 18:39). Sin embargo, en Ro 16:25 Pablo lleva la palabra a un registro más grandioso: el misterio ''guardado en silencio'' (σεσιγημένου) durante largos siglos ha sido ahora revelado. Aquí el silencio se convierte en secreto a escala cósmica — no un momento de quietud sino una era de ocultamiento abierta por el evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4603', 'spa', 'De hierro; que describe objetos o instrumentos hechos de hierro, a menudo transmitiendo fuerza o autoridad inquebrantable.', 'Adjetivo que significa "hecho de hierro", usado en el Nuevo Testamento para describir objetos de poder formidable e inquebrantable. En Apocalipsis, la imagen recurrente de la vara de hierro (σιδηρᾶν ῥάβδον) retrata el gobierno soberano absoluto del Mesias (Ap 2:27; 12:5; 19:15), mientras que Hechos 12:10 se refiere a la puerta de hierro literal de la prision de Pedro. Las cinco ocurrencias neotestamentarias comparten un unico nucleo semantico: compuesto de hierro, con resonancias metaforicas de autoridad invencible cuando se aplica al dominio mesianico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4605', 'spa', 'Sidón, la antigua ciudad costera fenicia emparejada con Tiro en los juicios proféticos y el ministerio de Jesús. Nombre propio de un prominente puerto', 'Sidón, la antigua ciudad costera fenicia emparejada con Tiro en los juicios proféticos y el ministerio de Jesús. Nombre propio de un prominente puerto fenicio en la costa del Mediterráneo, al norte de Tiro. En los Evangelios, Sidón aparece junto a Tiro como ciudad pagana que se habría arrepentido si hubiera presenciado los milagros de Jesús (Mt 11:21-22; Lc 10:13-14). Jesús mismo se retira a la región de Tiro y Sidón (Mt 15:21; Mr 7:31), y multitudes de Sidón vienen a escucharlo (Mr 3:8; Lc 6:17). En Hechos 27:3, Pablo se detiene en Sidón durante su viaje a Roma. El binomio ''Tiro y Sidón'' se volvió proverbial tanto en los oráculos de juicio como en la narrativa evangélica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4609', 'spa', 'Silas — un líder en la iglesia de Jerusalén que se convirtió en compañero misionero de Pablo. Silas (la forma aramea del latinizado Silvano) aparece 1', 'Silas — un líder en la iglesia de Jerusalén que se convirtió en compañero misionero de Pablo. Silas (la forma aramea del latinizado Silvano) aparece 13 veces en Hechos, trazando el arco de una figura significativa de la iglesia primitiva. Presentado primero como ''varón principal entre los hermanos'' elegido para llevar la carta del Concilio de Jerusalén a Antioquía (Hch 15:22), Silas pronto se convierte en el principal colaborador de Pablo en el segundo viaje misionero. Soporta el encarcelamiento en Filipos (Hch 16:25), es recibido en Tesalónica y Berea (Hch 17:4, 10) y se reúne con Pablo en Corinto (Hch 18:5). El nombre se mantiene estable en todas las traducciones, como es de esperar para un nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4610', 'spa', 'Silvano — compañero de Pablo, también conocido como Silas, coautor de cartas a Tesalónica y colaborador en Corinto.', 'Silvano es la forma latinizada del nombre Silas, e identifica a uno de los colaboradores más fieles de Pablo. Aparece en los saludos de ambas cartas a los Tesalonicenses junto a Timoteo (1 Ts 1:1; 2 Ts 1:1), es mencionado como coproclamador de Cristo en Corinto (2 Cor 1:19) y es señalado como portador fiel — o quizás amanuense — de 1 Pedro (1 Pe 5:12). El uso constante del nombre latino formal en las epístolas, frente a ''Silas'' en Hechos, probablemente refleja las convenciones de la correspondencia oficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4611', 'spa', 'Siloé; estanque en Jerusalén donde Jesús envió al ciego a lavarse', 'Siloé era un estanque en Jerusalén, alimentado por el manantial de Gihón a través del túnel de Ezequías. Su nombre significa «enviado» en hebreo. Aparece en Lucas como el lugar de un trágico accidente y en Juan como el sitio donde Jesús envió al ciego a lavarse para recibir la vista. El lugar posee un profundo significado tanto histórico como teológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4613', 'spa', 'Simon: nombre propio griego comun (del hebreo שִׁמְעוֹן), llevado por Simon Pedro y varios otros personajes del NT.', 'Simon es la forma helenizada del nombre hebreo שִׁמְעוֹן (Shimon), uno de los nombres propios mas frecuentes en el Nuevo Testamento. Lo llevan al menos nueve individuos distintos: Simon Pedro, el apostol principal (Mateo 4:18; 16:16); Simon el Zelote (Mateo 10:4); Simon de Cirene, que cargo la cruz de Jesus (Mateo 27:32); Simon el leproso de Betania (Mateo 26:6); Simon hermano de Jesus (Mateo 13:55); Simon el fariseo (Lucas 7:40); Simon el curtidor en Jope (Hechos 9:43; 10:6); Simon el Mago, hechicero samaritano (Hechos 8:9); y Simon Iscariote, padre de Judas (Juan 6:71). Son el contexto y los descriptores, no el nombre en si, los que los distinguen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4614', 'spa', 'Sinaí — el monte donde Dios entregó la Ley a Moisés, vinculado simbólicamente al antiguo pacto.', 'Sustantivo propio indeclinable que designa el monte desértico donde Dios descendió en fuego y trueno para entregar la Torá a Israel. En el discurso de Esteban ante el Sanedrín, Sinaí es el suelo sagrado donde Moisés encontró la zarza ardiente (Hch 7:30) y más tarde recibió los oráculos vivientes (Hch 7:38). La alegoría de Pablo en Gálatas 4:24-25 es teológicamente impactante: identifica el monte Sinaí con Agar y el pacto de esclavitud, contrastándolo con la libertad de la Jerusalén celestial. El nombre porta así tanto gravedad histórica como una poderosa resonancia tipológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4615', 'spa', 'Mostaza; la planta de mostaza (Sinapis), usada por Jesus como imagen parabolica del crecimiento del reino desde comienzos minusculos.', 'Palabra griega para mostaza, referida a la planta del genero Sinapis, conocida por su semilla extraordinariamente pequena que crece hasta convertirse en un arbusto grande. Jesus la emplea en dos contextos de ensenanza memorables: la parabola de la semilla de mostaza, que ilustra el crecimiento expansivo del reino de los cielos desde origenes humildes (Mt 13:31; Mr 4:31; Lc 13:19), y el dicho sobre la fe del tamano de un grano de mostaza, suficiente para mover montanas o arrancar arboles (Mt 17:20; Lc 17:6). Un unico referente botanico con enorme potencia parabolica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4616', 'spa', 'Tela de lino fino usada como vestidura o envoltura; en contextos funerarios, la sábana de lino en que se envuelve un cuerpo para sepultarlo.', 'Σινδών designa una pieza de lino fino, apreciada en el Mediterráneo antiguo por su calidad y versatilidad. Marcos la emplea dos veces en una misma escena: el joven misterioso en Getsemaní que huyó desnudo dejando su σινδών atrás (Mark 14:51-52). Pero su aparición más solemne es en la sepultura de Jesús, donde José de Arimatea compra una σινδών y envuelve en ella el cuerpo (Matt 27:59; Mark 15:46; Luke 23:53). En español, «sábana» captura bien su carácter de lienzo extendido, mientras que en alemán «Leinentuch» subraya el material de lino en sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4618', 'spa', 'engordado, cebado; animales criados y preparados para un banquete', 'Este adjetivo describe animales que han sido engordados o cebados para el sacrificio, particularmente para fiestas de celebración. En el uso clásico se aplicaba tanto a personas como a animales bien alimentados. Lucas lo emplea exclusivamente en la parábola del hijo pródigo para describir el becerro especial sacrificado para la celebración. El término resalta la abundancia y el espíritu festivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4621', 'spa', 'Trigo o grano; el cereal principal del antiguo Cercano Oriente, usado literal y figuradamente. El término griego estándar para el grano cultivado, más', 'Trigo o grano; el cereal principal del antiguo Cercano Oriente, usado literal y figuradamente. El término griego estándar para el grano cultivado, más frecuentemente trigo en particular. Aparece en algunas de las parábolas agrícolas más memorables de Jesús: el trigo y la cizaña (Mt 13:25-30), el grano de trigo que cae en tierra y muere (Jn 12:24). Cuando se usa de forma más amplia, denota provisiones de cereal o suministro alimentario, como cuando Jacob envió a sus hijos a Egipto por grano (Hch 7:12). El español distingue ''trigo'' (wheat) de ''grano'' (generic grain), insinuando el rango semántico más amplio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4622', 'spa', 'Sion; el monte santo y ciudad de Jerusalén, usado literal y simbólicamente para la morada de Dios y la ciudad celestial.', 'Σιών es la transliteración griega del hebreo צִיּוֹן, originalmente la fortaleza jebusea conquistada por David, que llegó a ser sinónimo de Jerusalén, el monte del templo y, en última instancia, el lugar escogido por Dios para habitar. En el Nuevo Testamento aparece exclusivamente en citas del Antiguo Testamento y declaraciones teológicas. Mateo 21:5 y Juan 12:15 citan Zacarías 9:9 sobre la «hija de Sion», mientras que Romanos 9:33 y 1 Pedro 2:6 citan a Isaías sobre la piedra angular puesta «en Sion». Hebreos 12:22 y Apocalipsis 14:1 elevan a Sion a una realidad celestial: «el monte Sion, la ciudad del Dios vivo».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4623', 'spa', 'Callar, guardar silencio, dejar de hablar o de hacer ruido. Se usa tanto de personas a quienes se manda callar como de una tormenta que es aquietada. ', 'Callar, guardar silencio, dejar de hablar o de hacer ruido. Se usa tanto de personas a quienes se manda callar como de una tormenta que es aquietada. En el Nuevo Testamento, la multitud reprende a los ciegos para que callen, pero ellos gritan más fuerte (Mt 20:31; Mr 10:48; Lc 18:39), y Jesús permanece en silencio ante el interrogatorio del sumo sacerdote (Mt 26:63). De manera especialmente dramática, Jesús ordena a la tormenta que calle (Mr 4:39) y el viento obedece, extendiendo el alcance de la palabra más allá del habla humana hacia la naturaleza misma. En Hch 18:9, el Señor le dice a Pablo que no calle sino que siga hablando. El español ''callar'' capta tanto la dimensión voluntaria como la impuesta de este silencio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4624', 'spa', 'Hacer tropezar o caer en pecado; en voz pasiva, escandalizarse, ofenderse o apartarse de la fe', 'Hacer tropezar o caer en pecado; en voz pasiva, escandalizarse, ofenderse o apartarse de la fe');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4625', 'spa', 'Tropiezo, trampa — cualquier cosa que cause caída espiritual, ofensa o entrampamiento. Σκάνδαλον originalmente se refería al gatillo de una trampa, el', 'Tropiezo, trampa — cualquier cosa que cause caída espiritual, ofensa o entrampamiento. Σκάνδαλον originalmente se refería al gatillo de una trampa, el mecanismo de cebo que hacía saltar el lazo. En tiempos del Nuevo Testamento, la palabra se había metaforizado completamente para denotar cualquier cosa que haga tropezar a alguien en pecado o ruina moral. Jesús advierte que los escándalos deben venir, pero pronuncia un ay sobre aquellos por quienes llegan (Mt 18:7). Incluso llama a Pedro σκάνδαλον cuando el discípulo se resiste a la cruz (Mt 16:23). El español ''escándalo'' y el francés ''scandale'' derivan directamente de esta raíz griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4626', 'spa', 'cavar; excavar la tierra para construir, cultivar u otros propósitos', 'Este verbo significa cavar o excavar la tierra. En el uso clásico incluía la excavación para cultivo, construcción y guerra. Jesús lo emplea en su enseñanza tanto en sentido literal (cavar cimientos, cavar alrededor de las vides) como metafórico (la queja del administrador deshonesto sobre su incapacidad para cavar). El término representa el trabajo manual y la preparación diligente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4627', 'spa', 'bote auxiliar, esquife; embarcación pequeña llevada o remolcada por un navío mayor', 'Este término náutico designa el bote auxiliar o esquife, la pequeña embarcación que los navíos de mayor tamaño llevaban a bordo o remolcaban para diversos usos. En el griego clásico se aplicaba a botes ligeros, embarcaciones de carga e incluso cunas infantiles, por la semejanza de forma. Lucas lo emplea exclusivamente en Hechos 27 durante el relato del naufragio de Pablo, para referirse al bote salvavidas que los marineros intentaron usar para escapar del barco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4628', 'spa', 'piernas; las extremidades inferiores desde la cadera hasta el pie', 'Este término anatómico designa las piernas, específicamente desde la cadera hacia abajo. En el uso clásico era una descripción anatómica directa, aplicada también a las patas de animales sacrificiales. Juan lo emplea exclusivamente en el relato de la crucifixión para describir el quebrantamiento de las piernas destinado a acelerar la muerte, un detalle de profunda relevancia teológica que confirma el cumplimiento de la profecía mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4632', 'spa', 'Vasija, recipiente o instrumento; enseres domésticos; aparejo o jarcia náutica', 'Vasija, recipiente o instrumento; enseres domésticos; aparejo o jarcia náutica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4633', 'spa', 'Tienda, enramada o tabernaculo; la tienda sagrada de la presencia de Dios o un refugio temporal ordinario. σκηνή es una de esas palabras donde un obje', 'Tienda, enramada o tabernaculo; la tienda sagrada de la presencia de Dios o un refugio temporal ordinario. σκηνή es una de esas palabras donde un objeto sencillo — una tienda de tela y postes — se abre hacia un vasto significado teologico. En la Septuaginta traduce regularmente el hebreo mishkan, el santuario portatil donde la gloria de Dios habitaba entre Israel. La carta a los Hebreos construye todo su argumento sacerdotal en torno a esta palabra, contrastando la σκηνή terrenal con el verdadero tabernaculo celestial (He 8:2; 9:2-3). En la Transfiguracion, la oferta de Pedro de construir tres σκηναί (Mt 17:4; Mc 9:5) evoca la Fiesta de los Tabernaculos mientras senala involuntariamente algo mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4637', 'spa', 'Habitar, morar en tienda, tabernacular; establecer residencia entre los hombres, evocando la presencia divina del tabernáculo.', 'Verbo que significa ''plantar tienda'' o ''habitar,'' cargado de profundo peso teológico procedente de la tradición veterotestamentaria del tabernáculo. Su uso más célebre aparece en Juan 1:14 — ''el Verbo se hizo carne y habitó (ἐσκήνωσεν) entre nosotros'' — donde la imagen de la tienda evoca deliberadamente la presencia de la shekiná de Dios en el tabernáculo del desierto. En Apocalipsis, el verbo describe la presencia protectora de Dios sobre su pueblo (Ap 7:15; 21:3) y la morada celestial donde habitan los santos (Ap 12:12; 13:6). La expresión española habitó en tienda preserva hermosamente el matiz tabernacular que se pierde en la mayoría de las traducciones modernas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4638', 'spa', 'morada, tienda, tabernáculo; lugar de habitación temporal o permanente', 'Este sustantivo designa una morada, tienda o tabernáculo: un lugar de habitación, ya sea temporal como una tienda o más permanente como un templo. En el uso clásico abarcaba alojamientos militares, tiendas y edificios sagrados. El Nuevo Testamento lo emplea tanto para moradas literales como metafóricamente para referirse al cuerpo como habitación transitoria del alma. El término enfatiza la idea de habitación y presencia divina entre los seres humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4639', 'spa', 'Sombra; zona oscura proyectada por un objeto, usada literal y figuradamente para la oscuridad espiritual, la muerte o un anticipo.', 'Σκιά posee una rica carga metafórica tanto en el griego clásico como en el bíblico. En sentido literal, significa la sombra o penumbra que proyecta un objeto, como cuando las aves anidan entre las ramas y disfrutan de su sombra (Marcos 4:32) o los enfermos esperan que la sombra de Pedro caiga sobre ellos para ser sanados (Hechos 5:15). En sentido figurado, evoca la «sombra de muerte» —esa profunda oscuridad existencial de la que amanece la luz (Mateo 4:16; Lucas 1:79, citando a Isaías). En Colosenses 2:17 y Hebreos 8:5 y 10:1, el término describe los ritos del Antiguo Testamento como «sombra» de los bienes venideros, no la realidad misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4640', 'spa', 'saltar o brincar de gozo; movimiento exuberante e incontenible que expresa alegría', 'Este verbo capta la expresión física de un gozo desbordante: saltar, brincar, dar saltos de alegría. En el Evangelio de Lucas aparece tres veces: dos describiendo al niño Juan el Bautista saltando en el vientre de Elisabet al oír el saludo de María (1:41, 44) y una en la enseñanza de Jesús sobre regocijarse ante la persecución (6:23). La palabra transmite un movimiento espontáneo e irreprimible, como el de animales jóvenes retozando en el campo. Es el gozo hecho visible a través del cuerpo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4641', 'spa', 'dureza de corazón; resistencia obstinada a la voluntad de Dios, insensibilidad u obstinación espiritual', 'Término compuesto (literalmente ''corazón duro'') que describe la terquedad espiritual y la insensibilidad moral. Jesús lo usa dos veces en contextos idénticos, al explicar por qué Moisés permitió el divorcio (Mt 19:8; Mr 10:5), y una vez al reprender a los once por no creer los testimonios de la resurrección (Mr 16:14). La palabra diagnostica una condición en la que el corazón se endurece y deja de responder a la verdad divina. No se trata de duda intelectual, sino de resistencia voluntaria que impide tanto la obediencia como la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4642', 'spa', 'σκληρός — duro, áspero, severo; describe algo rígido, inflexible o difícil de aceptar.', 'El adjetivo σκληρός (del cual el español deriva «esclerosis») abarca un espectro que va desde lo físicamente duro hasta lo metafóricamente áspero o severo. En el Nuevo Testamento se aplica a personas, palabras y fuerzas: un «amo duro» que cosecha donde no sembró (Matt 25:24), una «palabra dura» que escandaliza a los discípulos (John 6:60), los «aguijones» contra los cuales Saulo da coces (Acts 9:5; 26:14), vientos recios que impulsan naves (Jas 3:4) y las «cosas duras» que los pecadores impíos dicen contra Dios (Jude 15). La palabra «duro» en español refleja fielmente esta misma amplitud semántica que transita de lo literal a lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4645', 'spa', 'Endurecer o hacer obstinado; en voz pasiva/media, endurecerse, especialmente del corazón que se resiste a Dios.', 'Σκληρύνω parte de la imagen física de algo que se vuelve rígido e inflexible, y la traslada al ámbito espiritual. La Epístola a los Hebreos cita el Salmo 95 tres veces — «No endurezcáis vuestros corazones» (Heb 3:8, 3:15, 4:7) — convirtiendo el verbo en una alarma pastoral recurrente. Pablo invoca la prerrogativa soberana de Dios: «Endurece a quien quiere» (Rom 9:18). En voz pasiva, la palabra describe el trágico deslizamiento hacia la obstinación, como cuando algunos en Éfeso se iban endureciendo contra la enseñanza de Pablo (Acts 19:9). El español «endurecer» refleja fielmente este arco de lo concreto a lo metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4646', 'spa', 'Torcido, encorvado; en sentido figurado, perverso, moralmente corrupto o deshonesto', 'Este adjetivo significa literalmente encorvado o torcido, lo opuesto a recto (εὐθύς). En el griego clásico se aplicaba a ríos sinuosos y caminos curvos, pero en el Nuevo Testamento predomina su fuerza metafórica. Lucas 3:5 cita la visión de Isaías de que «lo torcido será enderezado», anunciando una renovación moral y cósmica. Pedro exhorta a salvarse de «esta generación perversa» (Hechos 2:40), y Pablo llama a los creyentes a resplandecer como lumbreras en medio de una «generación torcida y perversa» (Filipenses 2:15). En 1 Pedro 2:18 se aplica a amos severos o perversos, mostrando su alcance desde lo cósmico hasta lo doméstico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4648', 'spa', 'Mirar con atención o considerar cuidadosamente; también vigilar o estar en guardia contra algo o alguien.', 'Σκοπέω es el verbo detrás de la palabra inglesa «scope» — significa fijar la mirada en algo con intención, ya sea por admiración o por cautela. Pablo dice a los corintios que mantengan la vista en las realidades eternas invisibles en vez de las temporales visibles (2 Cor 4:18), y exhorta a los filipenses a considerar los intereses de los demás junto con los propios (Phil 2:4). Pero el mismo verbo también sirve de advertencia: «Vigilad a los que causan divisiones» (Rom 16:17). El paso de la contemplación a la vigilancia es natural, pues el hilo común es una atención enfocada y deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4650', 'spa', 'Esparcir, dispersar o diseminar; se usa para dispersar ovejas, personas o repartir generosamente recursos.', 'Verbo que significa ''esparcir'' o ''dispersar,'' empleado en el Nuevo Testamento tanto en sentido literal como figurado. Jesús lo cita en el proverbio sobre reunir y esparcir (Mt 12:30; Lc 11:23), advirtiendo que la neutralidad ante su misión equivale a oposición activa. En Juan 10:12, el lobo dispersa las ovejas cuando el asalariado huye, y en Juan 16:32 Jesús predice que sus discípulos serán dispersados. Pablo cita el Salmo 112:9 en 2 Corintios 9:9, donde esparcir adquiere un sentido positivo: la distribución generosa de dones a los pobres. El campo semántico abarca desde la dispersión hostil hasta el reparto benéfico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4651', 'spa', 'Escorpión; arácnido venenoso usado como símbolo de peligro, amenaza demoníaca o intención dañina.', 'Palabra griega para escorpión, el conocido arácnido venenoso del Mediterráneo y el Cercano Oriente. Jesús lo menciona en dos contextos de enseñanza: al conceder a sus discípulos autoridad para pisar serpientes y escorpiones (Lc 10:19), y en la pregunta retórica sobre un padre que da un escorpión en lugar de un huevo (Lc 11:12). En Apocalipsis 9, criaturas semejantes a escorpiones surgen del abismo con poder de atormentar mediante su aguijón (Ap 9:3, 5, 10), aprovechando la temible reputación del escorpión. Todas las traducciones conservan el referente zoológico literal, confirmando un único sentido concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4652', 'spa', 'Oscuro, tenebroso; que carece de luz, tanto en sentido literal (ausencia de luz física) como figurado (ceguera espiritual)', 'Adjetivo que describe lo que está envuelto en oscuridad o sombra. Jesús lo emplea en sus enseñanzas paralelas sobre el ojo como lámpara del cuerpo (Mt 6:23; Lc 11:34, 36). Si el ojo —fuente de iluminación interior— está «oscuro», toda la persona habita en tinieblas. El trasfondo griego clásico abarca tanto la oscuridad literal (noche, lugares sombríos) como la oscuridad metafórica (discurso confuso, intenciones ocultas). En la enseñanza de Jesús, un ojo «oscuro» sugiere ceguera espiritual o distorsión moral que sumerge a la persona entera en sombras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4653', 'spa', 'Oscuridad o tiniebla, tanto la ausencia fisica de luz como la oposicion moral y espiritual a la verdad divina. Mas que simplemente la ausencia de luz,', 'Oscuridad o tiniebla, tanto la ausencia fisica de luz como la oposicion moral y espiritual a la verdad divina. Mas que simplemente la ausencia de luz, σκοτία tiene un profundo peso teologico en los escritos joaninos. El Evangelio de Juan se abre con la declaracion de que ''la luz resplandece en las tinieblas, y las tinieblas no la dominaron'' (Jn 1:5), estableciendo la oscuridad como el ambito opuesto a la presencia reveladora de Dios. Jesus advierte a sus seguidores que no caminen en tinieblas para no tropezar (Jn 8:12; 12:35), y 1 Juan define el contraste moral con claridad: ''Dios es luz, y en el no hay tiniebla alguna'' (1 Jn 1:5). Mateo conserva el sentido profetico de un pueblo ''sentado en tinieblas'' esperando la luz (Mt 4:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4654', 'spa', 'Oscurecer, entenebrecer; usado para astros que pierden su luz y para mentes que caen en ceguera espiritual.', 'Verbo que significa ''oscurecer'' u ''oscurecerse,'' presente tanto en contextos cósmicos como espirituales. En el Discurso del Monte de los Olivos, Jesús profetiza que el sol y la luna se oscurecerán al final de los tiempos (Mt 24:29; Mc 13:24), recogiendo la imaginería veterotestamentaria del día del Señor. Pablo aplica el vocablo a la ceguera espiritual: corazones entenebrecidos por pensamientos vanos (Ro 1:21) y ojos oscurecidos como castigo judicial (Ro 11:10, citando Sal 69:23). Apocalipsis 8:12 describe la tercera parte de los astros heridos de oscuridad. El campo semántico abarca el oscurecimiento físico y el enceguecimiento espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4655', 'spa', 'Oscuridad, tinieblas; ausencia física de luz y ceguera espiritual-moral metafórica o juicio divino', 'Oscuridad, tinieblas; ausencia física de luz y ceguera espiritual-moral metafórica o juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4656', 'spa', 'Oscurecer, entenebrecer; privar de luz u ofuscar, ya sea en sentido literal o figurado', 'Verbo que significa hacer oscuro, ofuscar o cegar. Aparece en Efesios 4:18 para describir a los gentiles cuyo entendimiento ha sido entenebrecido, y dos veces en Apocalipsis retratando oscurecimientos cósmicos: el sol y el aire oscurecidos por humo (9:2) y un reino sumido en tinieblas (16:10). Las formas pasivas («siendo oscurecido», «habiendo sido oscurecido») sugieren tanto proceso como resultado: la luz falla, la visión se apaga, la comprensión se desvanece. Los usos clásicos incluyen cegar, aturdir o causar vértigo, todos vinculados a la pérdida de claridad u orientación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4660', 'spa', 'Molestar, importunar, acosar; fatigar o angustiar a alguien imponiéndole una carga', 'Originalmente significaba desollar o desgarrar (relacionado con σκῦλον, ''despojos arrancados al enemigo caído''), pero en el griego koiné se suavizó hasta significar molestar o importunar. Sus apariciones en el NT siguen dos patrones vívidos. En Mateo 9:36, Jesús ve a las multitudes «acosadas y desamparadas», describiendo su agotamiento espiritual bajo un liderazgo deficiente. En Marcos 5:35 y Lucas 8:49, unos mensajeros le dicen a un padre angustiado que no «moleste» más a Jesús, pues la niña ha muerto. En Lucas 7:6 se le dice a Jesús que no se «moleste» en ir a la casa del centurión. Cada uso conlleva la emoción de alguien que soporta más de lo debido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4663', 'spa', 'Gusano; larva o lombriz que se alimenta de materia en descomposición', 'Palabra griega para gusano, en particular lombrices de tierra o larvas de insectos. En el NT aparece exclusivamente en Marcos 9:44, 46, 48, dentro de la advertencia de Jesús sobre la Gehena, donde «su gusano no muere y el fuego no se apaga», haciéndose eco de Isaías 66:24. La imagen es cruda: gusanos que consumen perpetuamente sin saciarse jamás, simbolizando una destrucción sin fin. En el griego clásico se usa para diversos gusanos y larvas hallados en el estiércol, la materia putrefacta o los árboles infestados, criaturas asociadas con la corrupción y la muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4668', 'spa', 'Esmirna; importante ciudad de Jonia en la costa egea de Asia Menor', 'Esmirna fue una de las grandes ciudades de la antigua Jonia, ubicada en la costa del mar Egeo de lo que hoy es Turquía. La ciudad tenía raíces antiguas mencionadas por Homero y fue refundada como un importante centro urbano helenístico y romano. Funcionó como un puerto y centro comercial de primer orden, y llegó a albergar una de las siete iglesias a las que se dirige el libro de Apocalipsis. Su nombre aparece en diversas formas griegas, y algunas inscripciones registran Ζμύρνα con zeta en vez de sigma. Sus habitantes, llamados Σμυρναῖοι, se enorgullecían de la cultura, el comercio y, más tarde, de la comunidad cristiana que soportó la persecución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4670', 'spa', 'Sodoma, la ciudad destruida de la llanura, sinónimo de maldad extrema y juicio divino. Nombre propio de la infame ciudad destruida con fuego y azufre ', 'Sodoma, la ciudad destruida de la llanura, sinónimo de maldad extrema y juicio divino. Nombre propio de la infame ciudad destruida con fuego y azufre en Génesis 19, invocada a lo largo del Nuevo Testamento como el ejemplo supremo del juicio divino sobre el pecado. Jesús advierte que el día del juicio será más tolerable para Sodoma que para las ciudades que rechazan a sus mensajeros (Mt 10:15; 11:23-24). Pablo cita el oráculo de Isaías sobre Sodoma para ilustrar la misericordia de Dios al preservar un remanente de Israel (Ro 9:29). Pedro y Judas usan la destrucción de Sodoma como paradigma de advertencia para los impíos (2 P 2:6; Jud 7). Apocalipsis llama simbólicamente a Jerusalén ''Sodoma'' (Ap 11:8). El nombre se convirtió en un referente moral universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4671', 'spa', 'tú (singular), tu/tuyo; pronombre de segunda persona singular en genitivo (σου) o dativo (σοι)', 'Estas son las formas de genitivo y dativo del pronombre personal de segunda persona singular: σου («de ti, tu/tuyo») y σοι («a ti, para ti»). Aparecen constantemente en el griego bíblico para indicar posesión («tu casa»), objetos indirectos («te doy») y diversas relaciones preposicionales. La forma enclítica σου podía perder su acento al seguir a otra palabra, mientras que σοι se mantenía distinta. El sistema de casos del griego antiguo hacía imprescindibles estas formas para señalar las relaciones entre los verbos y sus complementos personales. En el discurso directo, las oraciones y los mandamientos, estas formas creaban un trato personal íntimo que el «tú» del español moderno solo capta parcialmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4672', 'spa', 'Σολομών (Solomōn) — Salomón; el hijo de David y Betsabé, el proverbialmente sabio rey de Israel. El nombre propio Salomón se refiere al hijo de David ', 'Σολομών (Solomōn) — Salomón; el hijo de David y Betsabé, el proverbialmente sabio rey de Israel. El nombre propio Salomón se refiere al hijo de David que le sucedió como rey sobre Israel, renombrado sobre todo por su sabiduría dada por Dios y la magnificencia de su reinado. La genealogía de Mateo lo identifica con precisión: ''David engendró a Salomón de la que fue mujer de Urías'' (Mt 1:6-7). Jesús invoca el esplendor de Salomón como contraste de la providencia divina — ''ni siquiera Salomón con toda su gloria se vistió como uno de estos'' (Mt 6:29; Lc 12:27) — y su sabiduría como contraste de su propia autoridad: ''algo mayor que Salomón está aquí'' (Mt 12:42; Lc 11:31). En Jn 10:23 y Hch 3:11; 5:12, el ''Pórtico de Salomón'' preserva su nombre en la arquitectura del complejo del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4674', 'spa', 'tu, tuyo — pronombre posesivo de segunda persona singular que indica pertenencia al interlocutor', 'tu, tuyo — pronombre posesivo de segunda persona singular que indica pertenencia al interlocutor');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4675', 'spa', 'tu, tuyo/a; pronombre posesivo de segunda persona singular (forma de genitivo usada como posesivo)', 'Esta es la forma de genitivo del pronombre personal de segunda persona singular que funciona como posesivo: «tu» o «tuyo». El griego empleaba regularmente el caso genitivo de los pronombres personales para expresar posesión, en lugar de contar con adjetivos posesivos separados para todas las personas. Así, σοῦ o su forma enclítica σου significaba «de ti» o «tu», y aparecía en contextos como «tu padre», «tu fe», «tu casa». La forma podía ser enfática o enclítica según el grado de énfasis requerido. Este rasgo gramatical hacía que los pronombres griegos fueran sumamente eficientes, al tiempo que mantenían una distinción clara entre el «tu» singular y el «vuestro» plural, diferencia que el español conserva de modo natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4676', 'spa', 'Paño para enjugar el sudor; sudario, pañuelo o lienzo — usado para envolver y en la sepultura', 'Tomado directamente del latín sudarium (de sudor, ''sudor''), este término designa un paño pequeño usado originalmente para secar la transpiración del rostro. En el Nuevo Testamento aparece en contextos notablemente variados. El siervo infiel envuelve la mina de su señor en un sudario (Lucas 19:20), algo semejante a un pañuelo. En la tumba de Lázaro, el lienzo había sido atado alrededor de su rostro (Juan 11:44), y en el sepulcro vacío de Jesús se encontró enrollado aparte de las vendas de lino (Juan 20:7), un detalle exclusivo de Juan. En Hechos 19:12, paños llevados desde el cuerpo de Pablo sanaban a los enfermos, mostrando el rango de la palabra desde la costumbre funeraria hasta el ministerio milagroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4678', 'spa', 'Sabiduria: destreza, discernimiento o prudencia; en la Escritura, el atributo divino y su reflejo humano en el buen vivir.', 'Σοφία abarca desde la habilidad artesanal en el griego clasico hasta el concepto teologico supremo de la sabiduria divina. En sus 51 apariciones neotestamentarias, se presenta como la sabiduria de Dios vindicada por sus obras (Mateo 11:19), la sabiduria de Salomon (Mateo 12:42) y la asombrosa sabiduria de Jesus que escandalizo a Nazaret (Mateo 13:54; Marcos 6:2). Pablo la redefine radicalmente: la cruz es la sabiduria de Dios, locura para el mundo pero poder para los llamados (1 Corintios 1:24, 30). El espanol ''sabiduria'' converge con el frances ''sagesse'' y el aleman ''Weisheit'' en este concepto unitario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4680', 'spa', 'Sabio, habil, instruido; que posee sabiduria practica o discernimiento profundo, usado tanto de los verdaderamente sabios como de los que se considera', 'Sabio, habil, instruido; que posee sabiduria practica o discernimiento profundo, usado tanto de los verdaderamente sabios como de los que se consideran tales. En el griego clasico, este adjetivo abarcaba desde ''habil'' (referido a un escultor o musico) hasta ''prudente'' o ''astuto''. El Nuevo Testamento lo agudiza en un contraste entre la sabiduria divina y la humana. Jesus da gracias al Padre por haber escondido estas cosas ''de los sabios y entendidos'' (Mt 11:25; Lc 10:21), mientras Pablo pregunta ''¿Donde esta el sabio?'' (1 Co 1:20) y advierte contra ser ''sabio en vuestra propia opinion'' (Ro 12:16). Sin embargo, la palabra no siempre es ironica: Pablo tambien habla de los creyentes como sabios maestros constructores (1 Co 3:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4682', 'spa', 'Convulsionar, desgarrar; sacudir con espasmos violentos; usado para las crisis demoníacas que causan contorsiones corporales', 'Verbo que describe un desgarro violento, convulsiones o sacudidas, usado a menudo para animales salvajes que arrancan la carne del hueso. En el NT, los tres usos describen demonios que arrojan a sus víctimas en convulsiones antes de abandonarlas (Mc 1:26; 9:26; Lc 9:39). El trasfondo clásico incluye heridas de combate, desgarramientos por ira y espasmos médicos. Los evangelistas captan la naturaleza violenta e incontrolable de la aflicción demoníaca: cuerpos sacudidos y azotados, desgarrados por fuerzas que superan el dominio humano, liberados solo cuando Jesús lo ordena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4686', 'spa', 'Cohorte militar romana; destacamento de soldados, típicamente unos 600 hombres, estacionado como unidad de guarnición.', 'En su sentido griego original, σπεῖρα significaba cualquier cosa enrollada o retorcida —una cuerda, los anillos de una serpiente, un ovillo de hilo. Pero en el Nuevo Testamento de la era romana, designa exclusivamente una «cohorte», la unidad militar estándar romana de aproximadamente 600 soldados. Aparece en momentos clave: los soldados que se burlan de Jesús tras su juicio son «toda la cohorte» (Mt 27:27; Mc 15:16), el grupo de arresto en Getsemaní incluye una σπεῖρα con oficiales (Jn 18:3, 12), y en Hechos nombra a la Cohorte Italiana de Cornelio (Hch 10:1) y a la Cohorte Augusta que escolta a Pablo (Hch 27:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4687', 'spa', 'Sembrar semilla; usado para plantar, para lo sembrado y para el sembrador en la parabola.', 'Uno de los verbos agricolas mas vividos del Nuevo Testamento, σπείρω describe el acto de esparcir semilla sobre tierra preparada. Jesus lo hizo central en su ensenanza a traves de la Parabola del Sembrador (Mateo 13:3-23), donde la palabra misma aparece en formas activas, pasivas y participiales para describir al sembrador, el acto de sembrar y los diversos destinos de lo sembrado. Pablo lo extiende con fuerza en 1 Corintios 15:42-44 para describir el cuerpo de resurreccion ''sembrado en corrupcion, resucitado en incorrupcion'', y en Galatas 6:7-8 para la siembra en la carne versus en el Espiritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4690', 'spa', 'Simiente; descendencia o descendientes (esp. la simiente de Abraham); semillas literales en contexto agrícola o de contraste teológico', 'Simiente; descendencia o descendientes (esp. la simiente de Abraham); semillas literales en contexto agrícola o de contraste teológico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4692', 'spa', 'σπεύδω — apresurarse, darse prisa, moverse con urgencia o rapidez anhelante.', 'El verbo σπεύδω expresa movimiento urgente y ansioso: apresurarse hacia una persona, un lugar o una acción. Sus apariciones en el Nuevo Testamento son vívidas y concretas: los pastores se apresuraron a Belén para encontrar al Cristo recién nacido (Luke 2:16), Jesús mandó a Zaqueo bajar rápidamente del sicómoro (Luke 19:5) y Zaqueo bajó apresuradamente con gozo (Luke 19:6). Pablo se daba prisa por llegar a Jerusalén para Pentecostés (Acts 20:16), y el Señor le dijo que saliera de Jerusalén sin demora (Acts 22:18). En 2 Peter 3:12, se dice que los creyentes «apresuran» la venida del día de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4693', 'spa', 'σπήλαιον — cueva o guarida; cavidad rocosa natural usada como refugio, escondite o lugar de sepultura', 'El sustantivo neutro σπήλαιον designa una cueva, gruta o guarida: un espacio hueco natural o excavado en la roca. En los Evangelios Sinópticos aparece en la cita que Jesús hace de Jeremías 7:11 al purificar el templo: ''la habéis hecho cueva de ladrones'' (Mat 21:13; Mar 11:17; Luc 19:46), donde la imagen de la cueva evoca el escondite de bandidos. Juan lo emplea para la cueva-tumba de Lázaro (Juan 11:38), y Hebreos 11:38 describe a los fieles que anduvieron errantes por cuevas y cavernas de la tierra. Apocalipsis 6:15 retrata a los poderosos ocultándose en cuevas ante la ira divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4697', 'spa', 'σπλαγχνίζομαι (splanchnizomai) — ser movido a profunda compasión, sentir piedad visceral; misericordia entrañable que impulsa a la acción. Este verbo ', 'σπλαγχνίζομαι (splanchnizomai) — ser movido a profunda compasión, sentir piedad visceral; misericordia entrañable que impulsa a la acción. Este verbo deponente deriva de σπλάγχνα (''entrañas, vísceras''), situando su registro emocional en las entrañas más que en la cabeza. En el Nuevo Testamento se reserva casi exclusivamente para Jesús y para personajes de sus parábolas que reflejan la misericordia divina. Jesús es ''movido a compasión'' al ver multitudes como ovejas sin pastor (Mt 9:36), las multitudes hambrientas (Mt 14:14; 15:32; Mc 6:34; 8:2), los ciegos en Jericó (Mt 20:34) y un leproso (Mc 1:41). En las parábolas, el rey que perdona (Mt 18:27), el buen samaritano (Lc 10:33) y el padre que espera al hijo pródigo (Lc 15:20) experimentan esta misma respuesta visceral. Es compasión que mueve a actuar, nunca mero sentimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4698', 'spa', 'Entrañas, vísceras; en sentido figurado, afecto profundo, tierna compasión, misericordia sentida en lo más íntimo. En el griego clásico este término d', 'Entrañas, vísceras; en sentido figurado, afecto profundo, tierna compasión, misericordia sentida en lo más íntimo. En el griego clásico este término designaba los órganos viscerales —corazón, pulmones, hígado, riñones— las partes reservadas para los sacrificadores al inicio de un banquete. Para la época del Nuevo Testamento se había convertido en la expresión por excelencia para la sede más profunda de la emoción humana, de modo similar a como en el español antiguo se ubicaban los sentimientos en las ''entrañas''. Pablo escribe que anhela a los filipenses ''con las σπλάγχνα de Cristo Jesús'' (Fil 1:8), y el cántico de Zacarías celebra las ''σπλάγχνα de misericordia'' de Dios (Lc 1:78). El español ''entrañas'' y el francés ''entrailles'' conservan esta llamativa transferencia del cuerpo a la emoción. Solo una vez aparece el sentido anatómico literal: en el sombrío relato de la muerte de Judas, donde su cuerpo se reventó y ''todas sus σπλάγχνα se derramaron'' (Hch 1:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4699', 'spa', 'Esponja; organismo marino poroso y absorbente usado para limpiar o empapar líquidos', 'Palabra griega común para esponja, una criatura marina porosa que se recolectaba y usaba para la limpieza, el baño y otras tareas que requerían absorción. En el NT aparece tres veces, todas en la crucifixión: los soldados empapan una esponja con vinagre y la acercan a los labios de Jesús sobre una caña (Mt 27:48; Mc 15:36; Jn 19:29). Este humilde objeto cotidiano se convierte en instrumento de una pequeña misericordia —o burla— en los momentos finales de Cristo. Las fuentes clásicas mencionan esponjas para limpiar mesas, bañarse y lustrar calzado, mostrando su utilidad doméstica habitual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4700', 'spa', 'ceniza; el residuo en polvo que queda tras la combustion, usado en rituales de duelo o purificacion', 'El termino griego para ceniza, lo que queda despues de que el fuego ha consumido madera u otros materiales combustibles. En el NT aparece en la reprension de Jesus a las ciudades galileas (Mt 11:21, Lc 10:13), donde dice que Tiro y Sidon habrian hecho penitencia ''con cilicio y ceniza'', y en Hebreos 9:13, en relacion con el uso ritual de la ceniza de una becerra para purificacion. La ceniza simboliza duelo, arrepentimiento y fragilidad humana (''polvo eres y al polvo volveras''). Esparcir ceniza sobre la cabeza o sentarse en ceniza expresaba dolor y contricion, haciendo visible una actitud interior de humildad ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4702', 'spa', 'sembrados, campos de grano; tierra cultivada apta para la siembra o actualmente sembrada con cereales', 'Adjetivo que significa ''sembrado'' o ''apto para sembrar'', usado sustantivamente en plural para designar campos de grano o tierras de cultivo. Las tres apariciones en el NT corresponden a la controversia sobre el sabado: los discipulos de Jesus arrancan espigas mientras caminan por los sembrados (Mt 12:1, Mc 2:23, Lc 6:1). Los fariseos objetan, lo que da pie a la defensa de Jesus usando el ejemplo de David y el principio de que la necesidad humana y la misericordia superan las restricciones rituales. Son campos en produccion, sembrados y con cosecha, columna vertebral economica de la sociedad agricola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4703', 'spa', 'σπόρος — semilla; lo que se siembra, ya sea grano literal o figuradamente la palabra de Dios', 'Derivado de σπείρω (''sembrar''), σπόρος designa la semilla en su sentido agrícola: el grano que el agricultor arroja sobre la tierra. En las parábolas sinópticas lleva peso tanto literal como figurado: el sembrador sale a sembrar su semilla (Luc 8:5) y Jesús explica que ''la semilla es la palabra de Dios'' (Luc 8:11). Pablo extiende la metáfora en 2 Corintios 9:10, donde Dios provee ''semilla al que siembra'' como figura de provisión generosa. La extensión figurada hacia la palabra divina y la provisión surge naturalmente del contexto parabólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4704', 'spa', 'Ser diligente, esforzarse al máximo — perseguir una meta con celo ferviente, urgencia y esfuerzo persistente. El verbo σπουδάζω (spoudazō) transmite u', 'Ser diligente, esforzarse al máximo — perseguir una meta con celo ferviente, urgencia y esfuerzo persistente. El verbo σπουδάζω (spoudazō) transmite un empeño ferviente y afanoso — no un deber a regañadientes sino una urgencia de todo corazón. Pablo recuerda haber sido ''solícito'' en ayudar a los pobres (Gá 2:10) e insta a los efesios a ser ''diligentes en guardar la unidad del Espíritu'' (Ef 4:3). A Timoteo se le dice que se esfuerce por ''presentarse aprobado ante Dios'' (2 Ti 2:15) y que venga pronto (2 Ti 4:9). Pedro lo usa tres veces: ''Poned todo empeño en confirmar vuestra vocación'' (2 P 1:10), en asegurar el recuerdo (2 P 1:15) y en ''ser hallados por él en paz'' (2 P 3:14). Hebreos 4:11 exhorta a los creyentes a ''esforzarse por entrar en aquel reposo''. El español ''esforzarse'' refleja bien el matiz de empeño y exigencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4705', 'spa', 'diligente, fervoroso, celoso; que muestra empeño y compromiso serio en la busqueda de algo', 'Adjetivo que describe a alguien entusiasta, fervoroso y diligente, no casual ni tibio, sino seriamente comprometido. Las tres apariciones en el NT provienen de 2 Corintios 8, donde Pablo describe el interes fervoroso de Tito y de otro hermano por los corintios y su ofrenda (8:17, 22 dos veces). La palabra conlleva matices de prontitud y energia, pero denota principalmente seriedad moral y celo. En el griego clasico se aplica a buenos ciudadanos, artesanos habiles y personas virtuosas: aquellos que sobresalen porque se interesan profundamente y actuan en consecuencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4706', 'spa', 'seriedad, diligencia, excelencia; cualidad de ser celoso, diligente o moralmente bueno', 'Este sustantivo abstracto designa la cualidad de seriedad o empeño en el carácter, derivado de σπουδή (premura, celo). En contextos morales significaba bondad o excelencia de carácter, esa clase de seriedad que distinguía a las personas dignas de confianza. La Septuaginta lo empleó para describir cualidades éticas, mientras que los autores del Nuevo Testamento lo usaron para referirse al celo ferviente que debía caracterizar el servicio cristiano. La palabra captaba tanto la intensidad del esfuerzo como la calidad moral: no se trataba solo de trabajar con ahínco, sino de hacerlo con propósito serio e integridad ética. Se oponía a la negligencia, la frivolidad o el compromiso moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4707', 'spa', 'diligente, celoso, excelente; que describe esfuerzo serio, cualidad moral o superioridad en su clase', 'Este adjetivo, derivado de σπουδή (celo, premura), describe a personas o cosas marcadas por la diligencia, el fervor o la excelencia. Podía significar simplemente ''rápido'' o ''apresurado'', pero con mayor frecuencia indicaba un compromiso serio y celoso con una tarea, lo opuesto a la pereza o la negligencia. En contextos morales significaba ''bueno'' o ''excelente'', distinguiendo a las personas virtuosas de las malvadas. Un músico σπουδαῖος era uno excelente, no meramente un aficionado entusiasta. La palabra captaba la admiración griega por la energía enfocada aplicada con destreza y propósito moral. Los escritores del Nuevo Testamento la emplearon para el celo ferviente esperado en la vida y el servicio cristianos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4709', 'spa', 'diligentemente, con empeño, fervorosamente; con afan y esfuerzo serio, no de manera descuidada', 'Forma adverbial de ''fervoroso'' (G4705), que significa diligentemente, con afan, con esfuerzo serio. Aparece tres veces: los ancianos judios ruegan ''encarecidamente'' a Jesus por el centurion (Lc 7:4), Onesiforo busco ''diligentemente'' a Pablo en Roma (2 Ti 1:17), y Pablo insta a Tito a ayudar ''diligentemente'' a Zenas y Apolos (Tit 3:13). Cada contexto destaca un esfuerzo sostenido y deliberado, no intentos casuales, sino accion persistente impulsada por genuina preocupacion. El uso clasico incluye el sentido de premura, pero predomina la dimension moral de seriedad y esmero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4710', 'spa', 'Diligencia, celo ferviente o esfuerzo ardiente; también prisa o urgencia en la acción. Derivado del verbo σπεύδω (''apresurarse''), este sustantivo osci', 'Diligencia, celo ferviente o esfuerzo ardiente; también prisa o urgencia en la acción. Derivado del verbo σπεύδω (''apresurarse''), este sustantivo oscila entre disposición interior y urgencia exterior. En la mayoría de las ocurrencias neotestamentarias describe la cualidad moral de diligencia y celo ferviente: Pablo lo incluye entre las virtudes espirituales (Ro 12:8, 11), y la σπουδή de los corintios en respuesta a la carta de Pablo prueba su inocencia (2 Co 7:11-12). En dos vívidos pasajes narrativos, sin embargo, aflora el sentido clásico más antiguo de prisa física: Salomé regresa ''con prisa'' ante Herodes (Mc 6:25), y María se apresura hacia Elisabet ''con prisa'' por la región montañosa (Lc 1:39).');